/* «Рядом» — Yorùbá. Ключи — исходные русские строки. Перевод требует проверки носителем языка. */
(window.RYADOM_I18N = window.RYADOM_I18N || {})["yo"] = {"strings":{"Разделы":"Àwọn abala","Сегодня":"Òní","Мой дневник":"Ìwé ìrántí mi","Места":"Àwọn ibi","Игры":"Eré","Практики":"Àwọn ìdánrawò","Обо мне":"Nípa mi","Ты можешь идти в своём темпе.":"O lè lọ ní ìwọ̀n tìrẹ.","Здесь нет правильных ответов и обязательных серий дней.":"Kò sí ìdáhùn tó tọ̀nà tàbí ọjọ́ tí a gbọ́dọ̀ tò lẹ́sẹẹsẹ níbí.","Пространство для себя":"Àyè fún ara rẹ","Профиль":"Profaili","Как ты сегодня?":"Báwo ni o ṣe wà lónìí?","Можно честно. Начнём с того, что есть сейчас.":"O lè sọ òtítọ́. Jẹ́ ká bẹ̀rẹ̀ pẹ̀lú ohun tó wà báyìí.","С чего начать":"Ibi tí a ó ti bẹ̀rẹ̀","Поговорить":"Sọ̀rọ̀","Своими словами, без правил":"Pẹ̀lú ọ̀rọ̀ tìrẹ, láìsí òfin","Потренировать разговор":"Dánrawò ìjíròrò kan","Начальник, мама, отказ, извинение":"Ọ̀gá, ìyá, kíkọ̀, títọrọ àforíjì","Подобрать практику":"Yan ìdánrawò kan","Подходящую сейчас":"Èyí tó bá ìsinsìnyí mu","Рядом":"Ryadom","На твоей стороне":"Ní ẹ̀gbẹ́ rẹ","Напиши, что происходит…":"Kọ ohun tó ń ṣẹlẹ̀…","Написать сообщение":"Kọ ìfiránṣẹ́","Продиктовать сообщение":"Sọ ìfiránṣẹ́ jáde","Отправить":"Fi ránṣẹ́","Озвучивать ответы":"Ka àwọn ìdáhùn sókè","На сегодня":"Fún òní","Достаточно одного маленького шага":"Ìgbésẹ̀ kékeré kan tó","Не нужно исправлять весь день целиком.":"Kò pọn dandan láti tún gbogbo ọjọ́ ṣe.","Твоё пространство":"Àyè rẹ","Разговоры и отметки сохраняются только на этом устройстве.":"Àwọn ìjíròrò àti àkọsílẹ̀ wà lórí ẹ̀rọ yìí nìkan.","Последняя отметка":"Àkọsílẹ̀ tó kẹ́yìn","Пока нет":"Kò sí síbẹ̀","Открыть дневник →":"Ṣí ìwé ìrántí →","✦ ПРАКТИКА ДНЯ":"✦ ÌDÁNRAWÒ ÒNÍ","После трудного разговора":"Lẹ́yìn ìjíròrò tó le","4–6 минут · пройти →":"Ìṣẹ́jú 4–6 · bẹ̀rẹ̀ →","Только о тебе и твоём состоянии":"Nípa ìwọ àti bí o ṣe ń rí nìkan","Разговоры, ощущения и места, в которых прошёл твой день. Игровые истории хранятся отдельно.":"Àwọn ìjíròrò, ìmọ̀lára àti ibi tí ọjọ́ rẹ kọjá. A ń tọ́jú ìtàn eré lọ́tọ̀.","Календарь дня ↓":"Kàlẹ́ńdà ↓","7 дней":"Ọjọ́ 7","30 дней":"Ọjọ́ 30","Как сегодня внутри?":"Báwo ni inú rẹ ṣe rí lónìí?","Четыре отдельные отметки от 0 до 4. Это твои ощущения, а не медицинская оценка.":"Àmì mẹ́rin láti 0 sí 4. Ìmọ̀lára rẹ ni wọ́n, kì í ṣe àyẹ̀wò ìṣègùn.","Тревога":"Àníyàn","совсем нет":"rárá","очень сильно":"gidigbò gan-an","Грусть":"Ìbànújẹ́","Беспокойство":"Àìbalẹ̀ ọkàn","Спокойствие":"Ìfọ̀kànbalẹ̀","Что запомнилось сегодня?":"Kí ló dúró sí ọkàn rẹ lónìí?","(необязательно)":"(kò pọn dandan)","Можно отмечать раз в день. Сегодняшнюю отметку можно изменить.":"O lè kọ àkọsílẹ̀ lẹ́ẹ̀kan lójúmọ́. A lè yí ti òní padà.","Сохранить отметку":"Fi àkọsílẹ̀ pamọ́","Сильная тревога":"Àníyàn gidigbò","Нет отметок":"Kò sí àkọsílẹ̀","Сильная грусть":"Ìbànújẹ́ gidigbò","Много спокойствия":"Ìfọ̀kànbalẹ̀ púpọ̀","Как менялось состояние":"Bí ipò rẹ ṣe yí padà","Каждая точка — твоя отметка за день. Пропуски не считаются нулём.":"Àmì kọ̀ọ̀kan ni àkọsílẹ̀ ọjọ́ kan. Àwọn ọjọ́ tí o fò kò kà sí òdo.","Пока нет точек на графике. Поставь первую отметку выше.":"Kò sí àmì lórí àwòrán síbẹ̀. Ṣe àkọsílẹ̀ àkọ́kọ́ rẹ lókè.","0 — совсем нет":"0 — rárá","4 — очень сильно":"4 — gidigbò gan-an","Что можно заметить":"Ohun tí a lè kíyèsí","После трёх отметок здесь появится короткое наблюдение. Пропущенные дни не учитываются.":"Lẹ́yìn àkọsílẹ̀ mẹ́ta, àkíyèsí kékeré yóò hàn níbí. A kò ka àwọn ọjọ́ tí o fò.","Что помогает именно тебе":"Ohun tó ń ràn ọ́ lọ́wọ́ gan-an","Когда ты попробуешь практику и оценишь её, здесь появятся твои наблюдения.":"Tí o bá gbìyànjú ìdánrawò kan tí o sì díwọ̀n rẹ̀, àkíyèsí rẹ yóò hàn níbí.","Стереть дневник":"Pa ìwé ìrántí rẹ́","Календарь дня":"Kàlẹ́ńdà","Предыдущий месяц":"Oṣù tó kọjá","Следующий месяц":"Oṣù tó ń bọ̀","Пн":"Ajé","Вт":"Ìṣẹ́","Ср":"Ọjr","Чт":"Ọjb","Пт":"Ẹtì","Сб":"Àbá","Вс":"Àìk","Синяя точка — разговор, зелёная — место. Цвет дня — настроение; другие точки — отметка ощущений. Игровые события сюда не попадают.":"Àmì búlúù — ìjíròrò, ewé — ibi. Àwọ̀ ọjọ́ — ìṣesí; àwọn àmì míì — àkọsílẹ̀ ìmọ̀lára. Àwọn eré kò hàn níbí.","Пока нет записей за этот день. Можно добавить место, которое тебе запомнилось.":"Kò sí àkọsílẹ̀ fún ọjọ́ yìí síbẹ̀. O lè fi ibi tí o rántí kún un.","Места этого дня":"Àwọn ibi ọjọ́ náà","Пока пусто":"Ó ṣófo báyìí","Добавь посещённое место. Приложение не отслеживает перемещения автоматически.":"Fi ibi tí o lọ kún un. Àpù yìí kì í tọpinpin ìrìn rẹ fúnra rẹ̀.","＋ Добавить место":"＋ Fi ibi kún un","Места записываешь только ты. Они остаются на этом устройстве и не привязаны к игровому прогрессу.":"Ìwọ nìkan ló ń kọ àwọn ibi sílẹ̀. Wọ́n wà lórí ẹ̀rọ yìí, kò sì so mọ́ ìlọsíwájú eré.","Дневник хранится только на этом устройстве. Посещённые места добавляешь только ты; автоматического отслеживания перемещений нет.":"Ìwé ìrántí wà lórí ẹ̀rọ yìí nìkan. Ìwọ nìkan ló ń fi àwọn ibi tí o lọ kún un; kò sí títọpinpin ibi fúnra rẹ̀.","Место для этого момента":"Ibi fún àsìkò yìí","Куда под настроение?":"Ibo ni ká lọ gẹ́gẹ́ bí ìṣesí rẹ?","Иногда помогает сменить обстановку. Выбери, чего хочется сейчас, и посмотри места поблизости.":"Nígbà míì, yíyí àyíká padà máa ń ràn wá lọ́wọ́. Yan ohun tí o fẹ́ báyìí kí o wo àwọn ibi tó wà nítòsí.","Какое настроение?":"Ìṣesí wo ni?","☁ Грустно":"☁ Ìbànújẹ́","◌ Тревожно":"◌ Àníyàn","♡ Романтично":"♡ Ìfẹ́","✷ Весело":"✷ Ayọ̀","✿ Спокойно":"✿ Ìdákẹ́jẹ́","◇ Хочется нового":"◇ Nǹkan tuntun","☕ Устало":"☕ Àárẹ̀","↗ Хочется общения":"↗ Mo fẹ́ ẹgbẹ́","Можно выбрать настроение, а потом указать город или разрешить определить примерное местоположение.":"Yan ìṣesí kan, lẹ́yìn náà tẹ ìlú kan tàbí gbà kí a mọ ibi tí o wà ní àyíká.","Где искать?":"Ibo ni ká wá?","Геолокация запрашивается только по нажатию и не записывается в дневник. Поиск по названию города показывает места около его центра.":"A máa béèrè ibi tí o wà nígbà tí o bá tẹ̀ nìkan, a kò sì kọ ọ́ sínú ìwé ìrántí. Wíwá pẹ̀lú orúkọ ìlú ń fi àwọn ibi tó súnmọ́ àárín rẹ̀ hàn.","⌖ Рядом со мной":"⌖ Nítòsí mi","Или город / район":"Tàbí ìlú / àdúgbò","Например, Тбилиси":"àpẹẹrẹ, Ìbàdàn","Найти":"Wá","Выбери настроение и место поиска.":"Yan ìṣesí àti ibi tí a ó ti wá.","Место найдётся":"Ibi kan yóò yọ","Выбери настроение и нажми «Рядом со мной» или введи город. Любимые места из дневника появятся здесь первыми.":"Yan ìṣesí kí o sì tẹ “Nítòsí mi” tàbí kọ orúkọ ìlú. Àwọn ibi tí o fẹ́ràn nínú ìwé ìrántí yóò kọ́kọ́ hàn.","Порядок: сначала любимые, затем подходящие места по расстоянию. Рейтинги и популярность в соцсетях пока не доступны — мы не подменяем их количеством посещений.":"Ètò: àwọn tí o fẹ́ràn kọ́kọ́, lẹ́yìn náà àwọn ibi tó yẹ ní ìtòlẹ́sẹẹsẹ jíjìnnà. Kò sí ìdíwọ̀n tàbí òkìkí orí ayélujára síbẹ̀ — a kò fi iye ìbẹ̀wò rọ́pò wọn.","Моё: что я люблю":"Tèmi: ohun tí mo fẹ́ràn","Работает без интернета. Если поиск мест недоступен, подсказки берутся отсюда и из раздела «Обо мне».":"Ó ń ṣiṣẹ́ láìsí íńtánẹ́ẹ̀tì. Bí wíwá ibi kò bá ṣeé ṣe, àbá máa wá láti ibí àti “Nípa mi”.","Пока пусто. Добавь любимое место, блюдо или занятие: подсказки станут точнее.":"Ó ṣófo báyìí. Fi ibi, oúnjẹ tàbí ìṣe tí o fẹ́ràn kún un — àbá yóò túbọ̀ péye.","Что добавить":"Kí ni kí a fi kún un","Еда":"Oúnjẹ","Место":"Ibi","Занятие":"Ìṣe","например: кофейня у реки":"àpẹẹrẹ, ilé kọfí ẹ̀bá odò","Название или описание":"Orúkọ tàbí àpèjúwe","Добавить":"Fi kún un","Новые места: данные участников OpenStreetMap через Photon. Сведения могут быть неполными.":"Àwọn ibi tuntun: dátà àwọn olùkópa OpenStreetMap láti ọwọ́ Photon. Ìsọfúnni lè má pé.","Интерактивные истории":"Àwọn ìtàn alájọṣe","Игры про жизнь":"Eré nípa ìgbésí ayé","Герои, разговоры и решения, после которых меняется история.":"Àwọn akọni, ìjíròrò àti ìpinnu tó ń yí ìtàn padà.","Сюжетная игра · одна неделя":"Eré ìtàn · ọ̀sẹ̀ kan","Тихий город: неделя до ответа":"Ìlú ìdákẹ́jẹ́: ọ̀sẹ̀ kan kí a tó dáhùn (ní èdè Rọ́ṣíà)","Письмо о работе в другом городе, мама, папа, подруга и восемь слотов времени. На всё не хватит — и каждая встреча оставит след.":"Ìfilọ̀ iṣẹ́ ní ìlú míì, ìyá, bàbá, ọ̀rẹ́ kan àti àkókò mẹ́jọ. Kò ní tó fún gbogbo nǹkan — ìpàdé kọ̀ọ̀kan sì máa fi àmì sílẹ̀.","Одна неделя, восемь слотов, пять единиц сил":"Ọ̀sẹ̀ kan, àkókò mẹ́jọ, agbára márùn-ún","Начать историю →":"Bẹ̀rẹ̀ ìtàn →","Тренажёры разговоров":"Ìdánrawò ìjíròrò","Квесты, где выбор слов меняет ход разговора. Опираются на известные методики общения.":"Àwọn ìrìn àjò níbi tí yíyan ọ̀rọ̀ ń yí ìjíròrò padà. Ó dá lórí àwọn ọ̀nà ìbánisọ̀rọ̀ tí a mọ̀. Ní èdè Rọ́ṣíà nìkan báyìí.","КВЕСТ · 6 ШАГОВ · 2 СТИЛЯ":"ÌRÌN · ÌGBÉSẸ̀ 6 · Ọ̀NÀ 2","Разговор с начальником":"Ìjíròrò pẹ̀lú ọ̀gá","Трудная обратная связь. Неудачный ответ оставляет на месте, удачный пускает дальше и называет приём, на котором он держится.":"Èsì tó le. Ìdáhùn tí kò dára á mú ọ dúró sójú kan; èyí tó dára á gbé ọ síwájú, á sì dárúkọ ọgbọ́n tó wà lẹ́yìn rẹ̀.","Тренажёр разговора":"Ìdánrawò ìjíròrò","КВЕСТ · 5 ШАГОВ · 2 СТИЛЯ":"ÌRÌN · ÌGBÉSẸ̀ 5 · Ọ̀NÀ 2","Сказать «нет» коллеге":"Sísọ “rárá” fún alábàáṣiṣẹ́","Отказать на просьбу о выходных так, чтобы не поссориться: пауза, спокойное «нет», держать решение, предложить своё.":"Kíkọ ìbéèrè ìparí ọ̀sẹ̀ láìsí ìjà: dákẹ́ díẹ̀, “rárá” pẹ̀lú ìfọ̀kànbalẹ̀, dúró lórí ìpinnu, fi àbá tìrẹ lélẹ̀.","Границы на работе":"Ààlà níbi iṣẹ́","Разговор с мамой о границах":"Bíbá ìyá sọ̀rọ̀ nípa ààlà","Сохранить близость и право решать самому: признать чувства, сказать «я», договориться о понятном ритме.":"Pa ìsúnmọ́ra mọ́ àti ẹ̀tọ́ láti pinnu fúnra rẹ: gbà pé ìmọ̀lára wà, sọ̀rọ̀ pẹ̀lú “èmi”, fohùnṣọ̀kan lórí ìlànà tó ṣe kedere.","Границы в семье":"Ààlà nínú ẹbí","Извиниться и починить":"Tọrọ àforíjì kí o sì tún un ṣe","Подвели близкого человека. Как извиниться конкретно, выслушать и предложить, что исправите.":"O já ẹnìkan tó súnmọ́ ọ kulẹ̀. Bí o ṣe lè tọrọ àforíjì ní kedere, gbọ́ tirẹ̀, kí o sì sọ bí o ṣe máa tún un ṣe.","Конфликт и примирение":"Ìjà àti ìlàjà","Попросить о помощи":"Bíbéèrè fún ìrànlọ́wọ́","Попросить так, чтобы человеку было легко и согласиться, и отказать: конкретно, без извинений, с взаимностью.":"Béèrè lọ́nà tí yóò rọrùn fún ẹni náà láti gbà tàbí kọ̀: ní kedere, láìtọrọ àforíjì jù, pẹ̀lú àsanpadà.","Просьбы":"Ìbéèrè","Разговор о деньгах":"Ìjíròrò nípa owó","Обсудить неравные общие расходы без обвинений: факты, отражение, пропорциональное решение, срок сверки.":"Jíròrò lórí ìnáwó àjọpín tí kò dọ́gba láìdá ẹ̀bi: òtítọ́, títún ohun tí a gbọ́ sọ, ojútùú ìpín, ọjọ́ àyẹ̀wò.","Деньги и близкие":"Owó àti àwọn èèyàn wa","Сказать, что тебе нужно":"Sọ ohun tí o nílò","Попросить больше времени вместе, не обвиняя: мягкий старт, «я»-сообщение, валидация, небольшой эксперимент.":"Béèrè fún àkókò púpọ̀ sí i papọ̀ láìdá ẹ̀bi: ìbẹ̀rẹ̀ jẹ́jẹ́, ọ̀rọ̀ “èmi”, ìfọwọ́sí, àdánwò kékeré.","Отношения":"Àjọṣe","Отказать другу":"Kíkọ̀ fún ọ̀rẹ́","Отказаться от поездки так, чтобы дружба не пострадала: пауза, тёплое «нет», повтор решения, альтернатива.":"Kọ ìrìn àjò láìba ọ̀rẹ́ jẹ́: dákẹ́ díẹ̀, “rárá” tó lọ́yàyà, tún ìpinnu sọ, àyípadà míì.","Дружба и границы":"Ọ̀rẹ́ àti ààlà","Другие сюжетные направления · 12 коротких историй":"Àwọn ìtàn míì · ìtàn kúkúrú 12 (ní èdè Rọ́ṣíà)","Границы без ссоры":"Ààlà láìsí ìjà","Учиться говорить о своих возможностях и желаниях.":"Kọ́ láti sọ̀rọ̀ nípa ohun tí o lè ṣe àti ohun tí o fẹ́.","ИГРАТЬ · 2 ДНЯ":"ṢEERÉ · Ọ̀JỌ́ 2","Тревога и неопределённость":"Àníyàn àti àìdánilójú","Отличать риск от тревожных предположений.":"Ṣe ìyàtọ̀ láàrín ewu gidi àti àròjinlẹ̀ àníyàn.","ИГРАТЬ · 4 ГЛАВЫ":"ṢEERÉ · ORÍ 4","Внутренний критик":"Alárìíwísí inú","Находить более честный и бережный внутренний голос.":"Wá ohùn inú tó jẹ́ òtítọ́ tí ó sì jẹ́ jẹ́jẹ́.","Сложный разговор":"Ìjíròrò tó le","Тренировать фразы и слушать ответ собеседника.":"Dánrawò àwọn gbólóhùn kí o sì fetí sí èsì ẹnìkejì.","Когда нет сил":"Nígbà tí kò sí agbára","Планировать восстановление без гонки продуктивности.":"Gbèrò ìmúbọ̀sípò láìsí eré-ìje iṣẹ́.","Свои решения":"Ìpinnu tìrẹ","Замечать чужие ожидания и выбирать свой шаг.":"Kíyèsí ìrètí àwọn ẹlòmíì kí o sì yan ìgbésẹ̀ tìrẹ.","Отношения с собой":"Àjọṣe pẹ̀lú ara rẹ","Собирать опоры, которые не зависят от оценки других.":"Kó àwọn ìtìlẹ́yìn tí kò gbára lé èrò àwọn ẹlòmíì jọ.","Одиночество и близость":"Ìdánìkanwà àti ìsúnmọ́ra","Искать посильные способы установить контакт.":"Wá àwọn ọ̀nà tí ó ṣeé ṣe láti bá àwọn èèyàn sún mọ́.","Работа и выгорание":"Iṣẹ́ àti àárẹ̀ ọkàn","Замечать нагрузку и договариваться о границах.":"Kíyèsí ẹrù iṣẹ́ kí ẹ sì fohùnṣọ̀kan lórí ààlà.","Потеря и перемены":"Àdánù àti àyípadà","Давать место чувствам и искать поддержку.":"Fi àyè sílẹ̀ fún ìmọ̀lára kí o sì wá ìtìlẹ́yìn.","Тело и забота":"Ara àti ìtọ́jú","Замечать сигналы тела без оценивания внешности.":"Kíyèsí àmì ara láìdájọ́ ìrísí.","Отделять свои потребности от требований других.":"Ya àìní tìrẹ sọ́tọ̀ kúrò lára ìbéèrè àwọn ẹlòmíì.","Первая история — полноценная, на том же движке, что «Тихий город». Остальные одиннадцать — короткие зарисовки на четыре сцены, их предстоит переписать так же.":"Ìtàn àkọ́kọ́ pé, lórí ẹ̀rọ kan náà pẹ̀lú “Ìlú ìdákẹ́jẹ́”. Àwọn mọ́kànlá yòókù jẹ́ àwòrán kúkúrú onípele mẹ́rin tí a ó tún kọ bákan náà.","Инструменты на каждый день":"Irinṣẹ́ fún ojoojúmọ́","Библиотека практик":"Ilé-ìkàwé ìdánrawò","Выбирай то, что подходит моменту. Можно пропустить любой шаг.":"Yan èyí tó bá àsìkò mu. O lè fo ìgbésẹ̀ kankan.","ПРАКТИКА В ФОКУСЕ · 4–6 МИНУТ":"ÌDÁNRAWÒ PÀTÀKÌ · ÌṢẸ́JÚ 4–6","Когда слова ещё звучат в голове. Сначала найдём опору, затем разберём событие и выберем один посильный шаг.":"Nígbà tí ọ̀rọ̀ náà ṣì ń dún lórí rẹ. Lákọ̀ọ́kọ́, a ó wá ìtìlẹ́yìn, lẹ́yìn náà a ó tú ohun tó ṣẹlẹ̀ palẹ̀, a ó sì yan ìgbésẹ̀ kan tó ṣeé ṣe.","01 · Опора":"01 · Ìtìlẹ́yìn","02 · Ясность":"02 · Ìmọ́lẹ̀","03 · Действие":"03 · Ìṣe","Попробовать практику →":"Gbìyànjú ìdánrawò →","Подходит сейчас":"Ó bá ìsinsìnyí mu","Без сравнения":"Láìfiwéra","Заметь мысль «другие справляются лучше». Замени её на конкретный факт о сегодняшней нагрузке.":"Kíyèsí èrò “àwọn míì ń ṣe é dáadáa ju mi lọ”. Fi òtítọ́ kan pàtó nípa ẹrù òní rọ́pò rẹ̀.","Работа":"Iṣẹ́","Рабочая граница":"Ààlà níbi iṣẹ́","Назови реалистичный срок и то, что потребуется, чтобы уложиться. Не обещай невозможного.":"Dárúkọ àkókò tó bọ́gbọ́n mu àti ohun tí o nílò láti parí rẹ̀. Má ṣe ìlérí ohun tí kò ṣeé ṣe.","Злость":"Ìbínú","Граница одной фразой":"Ààlà ní gbólóhùn kan","Попробуй фразу: «Мне важно обсудить задачу, когда мы сможем говорить спокойно». Подстрой её под себя.":"Gbìyànjú gbólóhùn yìí: “Ó ṣe pàtàkì fún mi ká jíròrò iṣẹ́ náà nígbà tí a bá lè sọ̀rọ̀ pẹ̀lú ìfọ̀kànbalẹ̀.” Ṣe é bí ó ṣe bá ọ mu.","Маршруты: несколько шагов подряд":"Ọ̀nà: ìgbésẹ̀ mélòó kan lẹ́sẹẹsẹ","После трудного разговора с начальником":"Lẹ́yìn ìjíròrò tó le pẹ̀lú ọ̀gá","практика":"ìdánrawò","Вернуться в момент":"Padà sí àsìkò yìí","Отметить":"Sàmì sí i","После критики":"Lẹ́yìn àríwísí","Факты после встречи":"Òtítọ́ lẹ́yìn ìpàdé","тренажёр":"ìdánrawò","Ответ начальнику":"Dídáhùn fún ọ̀gá","Научиться говорить «нет»":"Kíkọ́ láti sọ “rárá”","Пауза перед ответом":"Ìdáduró kí o tó dáhùn","Право на нет":"Ẹ̀tọ́ láti kọ̀","Сложный разговор с близким":"Ìjíròrò tó le pẹ̀lú ẹnìkan tó súnmọ́ ọ","Сначала услышать":"Kọ́kọ́ gbọ́","Я-сообщение":"Ọ̀rọ̀ “èmi”","Близость и границы":"Ìsúnmọ́ra àti ààlà","Помириться после ссоры":"Ìlàjà lẹ́yìn ìjà","Моя часть":"Ipa tèmi","Тёплое сообщение":"Ìfiránṣẹ́ tó lọ́yàyà","Когда совсем нет сил":"Nígbà tí kò sí agbára rárá","Базовые нужды":"Àwọn àìní ìpìlẹ̀","Минимальный шаг":"Ìgbésẹ̀ tó kéré jù","Просьба о помощи":"Bíbéèrè ìrànlọ́wọ́","Тихая прогулка":"Ìrìn ìdákẹ́jẹ́","Спокойный вечер":"Ìrọ̀lẹ́ ìdákẹ́jẹ́","Вечерняя граница":"Ààlà ìrọ̀lẹ́","Выгрузить мысли":"Tú èrò jáde","Переход ко сну":"Ìmúrasílẹ̀ fún oorun","Поиск практики":"Wá ìdánrawò","Например: тревога, начальник, сон…":"àpẹẹrẹ: àníyàn, ọ̀gá, oorun…","Все":"Gbogbo","Перегрузка":"Ẹrù tó pọ̀ jù","Сон":"Oorun","Нет сил":"Kò sí agbára","Мысли":"Èrò","Мягкое дыхание":"Mímí jẹ́jẹ́","Замедлиться и почувствовать опору.":"Dín ìyára kù kí o sì nímọ̀lára ìtìlẹ́yìn.","Переключить внимание на то, что вокруг.":"Darí àfiyèsí sí ohun tó wà ní àyíká rẹ.","Слова и границы":"Ọ̀rọ̀ àti ààlà","Когда чужие слова задели слишком сильно.":"Nígbà tí ọ̀rọ̀ ẹlòmíì bá dùn ọ́ jù.","Разложить по полочкам":"Ṣe ètò rẹ̀","Отделить событие от мыслей о нём.":"Ya ìṣẹ̀lẹ̀ sọ́tọ̀ kúrò lára èrò rẹ nípa rẹ̀.","Тёплая фраза":"Gbólóhùn tó lọ́yàyà","Поддержать себя без требования быть сильнее.":"Ṣe ìtìlẹ́yìn fún ara rẹ láìfipá mú ara rẹ láti lágbára jù.","Смена обстановки":"Yí àyíká padà","Вода, движение или немного воздуха.":"Omi, ìṣípòpadà tàbí afẹ́fẹ́ díẹ̀.","Три опоры":"Ìtìlẹ́yìn mẹ́ta","Оглянись и назови три устойчивых предмета рядом. Почувствуй стопы на полу. Сделай один удобный выдох.":"Wò yíká kí o dárúkọ nǹkan mẹ́ta tó dúró ṣinṣin nítòsí. Nímọ̀lára ẹsẹ̀ rẹ lórí ilẹ̀. Mí jáde lẹ́ẹ̀kan pẹ̀lú ìrọ̀rùn.","Длинный выдох":"Mímí jáde gígùn","Вдохни естественно, затем выдохни немного медленнее. Повтори несколько раз без задержки дыхания и без усилия.":"Mí wọlé bí ó ṣe máa ń rí, lẹ́yìn náà mí jáde díẹ̀ lọ́ra jù. Tún un ṣe ní ìgbà díẹ̀ láìdá èémí dúró tàbí láìfipá.","Проверка фактов":"Ṣàyẹ̀wò òtítọ́","Запиши: что я знаю точно, что предполагаю и что могу уточнить. Не требуй от себя немедленного решения.":"Kọ ọ́ sílẹ̀: ohun tí mo mọ̀ dájú, ohun tí mo rò, àti ohun tí mo lè ṣàwárí. Má fipá mú ara rẹ láti pinnu lójú ẹsẹ̀.","План на ближайший час":"Ètò fún wákàtí tó ń bọ̀","Выбери одно безопасное и выполнимое действие на ближайший час. Остальное пока оставь на потом.":"Yan ìṣe kan tí kò léwu tí o sì lè ṣe fún wákàtí tó ń bọ̀. Fi ìyókù sílẹ̀ fún ìgbà míì.","Найди цвет":"Wá àwọ̀ kan","Выбери цвет и найди вокруг пять предметов этого цвета. Верни внимание к комнате, когда мысли ускоряются.":"Yan àwọ̀ kan kí o sì wá nǹkan márùn-ún tó ní àwọ̀ náà ní àyíká rẹ. Dá àfiyèsí padà sínú yàrá nígbà tí èrò bá ń sáré.","Контакт с поверхностью":"Ìfarakanra pẹ̀lú ilẹ̀","Заметь, как кресло или пол поддерживают тело. Опиши про себя три точки контакта.":"Kíyèsí bí àga tàbí ilẹ̀ ṣe gbé ara rẹ dúró. Ṣàpèjúwe ibi mẹ́ta tí ara rẹ fọwọ́ kàn nínú ọkàn rẹ.","Язык":"Èdè","Язык интерфейса, практик и разговора. Квесты и сюжетные игры пока на русском.":"Èdè ojú àpù, ìdánrawò àti ìjíròrò. Àwọn ìrìn àjò àti eré ìtàn wà ní èdè Rọ́ṣíà báyìí.","Только то, что рассказано тобой":"Ohun tí o sọ nìkan","Что обо мне известно":"Ohun tí a mọ̀ nípa mi","Чтобы «Рядом» мог подсказать, куда сходить, что поесть и что поможет, ему нужно знать тебя. Здесь видно всё, что он помнит. Записи остаются только на этом устройстве: любую можно удалить.":"Kí Ryadom tó lè dábàá ibi tí o lè lọ, ohun tí o lè jẹ àti ohun tí yóò ràn ọ́ lọ́wọ́, ó gbọ́dọ̀ mọ̀ ọ́. Gbogbo ohun tí ó rántí wà níbí. Àwọn àkọsílẹ̀ wà lórí ẹ̀rọ yìí nìkan, a sì lè pa èyíkéyìí rẹ́.","Использовать в разговоре и подсказках":"Lò ó nínú ìjíròrò àti àbá","Подтянуть из любимых мест":"Mú wá láti àwọn ibi tí o fẹ́ràn","Что люблю есть":"Oúnjẹ tí mo fẹ́ràn","блюда, кухня, вкусы":"oúnjẹ, ọ̀nà ìdáná, adùn","например: тёплый суп, кофе с булочкой":"àpẹẹrẹ: ọbẹ̀ gbígbóná, kọfí pẹ̀lú búrẹ́dì","Где мне хорошо":"Ibi tí ara mi ti ń balẹ̀","места и обстановка":"àwọn ibi àti àyíká","например: набережная, тихая библиотека":"àpẹẹrẹ: etí omi, ilé-ìkàwé ìdákẹ́jẹ́","Как люблю проводить время":"Bí mo ṣe fẹ́ràn láti lo àkókò","занятия и ритм":"àwọn ìṣe àti ìlànà","например: долгая прогулка, кино вечером":"àpẹẹrẹ: ìrìn gígùn, fíìmù ní ìrọ̀lẹ́","Что помогает, когда тяжело":"Ohun tó ń ṣèrànwọ́ nígbà tí nǹkan bá le","то, что правда работает":"ohun tó ń ṣiṣẹ́ gan-an","например: горячий чай, музыка в наушниках":"àpẹẹrẹ: tíì gbígbóná, orin lórí agbọ́rọ̀-etí","С кем мне легко":"Àwọn tí ara mi balẹ̀ pẹ̀lú wọn","люди и формат общения":"àwọn èèyàn àti ọ̀nà tí a fi ń wà papọ̀","например: с сестрой, один на один":"àpẹẹrẹ: pẹ̀lú àbúrò mi obìnrin, èmi àti òun nìkan","Чего лучше избегать":"Ohun tó dára jù láti yẹra fún","что выматывает или раздражает":"ohun tó ń mú àárẹ̀ tàbí ìbínú wá","например: шумные места, спешка":"àpẹẹrẹ: àwọn ibi aláriwo, ìkánjú","Стереть всё, что обо мне записано":"Pa gbogbo ohun tí a kọ nípa mi rẹ́","Дневник, места и игровой прогресс — отдельные данные: их очистка здесь не затрагивается.":"Ìwé ìrántí, àwọn ibi àti ìlọsíwájú eré jẹ́ dátà ọ̀tọ̀: pípa níbí kò kàn wọ́n.","Моя активность за 7 дней":"Ìṣe mi láàrín ọjọ́ 7","Считается только на этом устройстве и никуда не отправляется. Помогает понять, чем ты пользуешься.":"A ń kà á lórí ẹ̀rọ yìí nìkan, a kì í fi ránṣẹ́ sí ibikíbi. Ó ń ràn ọ́ lọ́wọ́ láti rí ohun tí o ń lò.","Пока нет данных.":"Kò sí dátà síbẹ̀.","Скопировать сводку":"Ṣe àdàkọ àkópọ̀","Сбросить счётчики":"Tún àwọn akọ̀wé-ìkà ṣe","Данные и конфиденциальность":"Dátà àti àṣírí","Всё, что ты вводишь, остаётся на этом устройстве. Здесь можно посмотреть, что хранится, сохранить копию или удалить всё.":"Gbogbo ohun tí o tẹ̀ sí wà lórí ẹ̀rọ yìí. Níbí o lè wo ohun tí a tọ́jú, fi ẹ̀dà pamọ́ tàbí pa gbogbo rẹ̀ rẹ́.","Другие данные приложения":"Dátà àpù míì","Сохранить копию файлом":"Fi ẹ̀dà pamọ́ bí fáìlì","Скопировать текст":"Ṣe àdàkọ ọ̀rọ̀","Восстановить из файла":"Dá padà láti inú fáìlì","Файл с данными":"Fáìlì dátà","Восстановить из вставленного текста":"Dá padà láti inú ọ̀rọ̀ tí a lẹ̀","Удалить все мои данные":"Pa gbogbo dátà mi rẹ́","Как приложение обращается с данными":"Bí àpù ṣe ń bójú tó dátà","Где хранятся.":"Ibi tí a ń tọ́jú rẹ̀.","В памяти браузера или приложения на этом устройстве. Учётных записей и серверной базы нет. Если очистить данные браузера или сменить устройство без копии, записи пропадут.":"Nínú ibi ìpamọ́ aṣàwákiri tàbí àpù lórí ẹ̀rọ yìí. Kò sí àkáǹtì tàbí ibi ìpamọ́ dátà lórí sáfà. Tí o bá pa dátà aṣàwákiri rẹ́ tàbí yí ẹ̀rọ padà láìní ẹ̀dà, àwọn àkọsílẹ̀ yóò sọnù.","Что передаётся наружу.":"Ohun tí a ń fi ránṣẹ́ síta.","Поиск мест: текст запроса и, если разрешишь, примерные координаты уходят в сервисы карт OpenStreetMap (Photon, Nominatim). Режим с сервером и ИИ, если он подключён: текст твоих сообщений уходит на сервер и к ИИ-провайдеру, чтобы получить ответ. Голосовой ввод и озвучка используют службы устройства.":"Wíwá ibi: ọ̀rọ̀ ìwádìí àti, tí o bá gbà, ibi tí o wà ní àyíká ń lọ sí iṣẹ́ àwòrán ilẹ̀ OpenStreetMap (Photon, Nominatim). Ipò sáfà àti AI tí wọ́n bá so pọ̀: ọ̀rọ̀ ìfiránṣẹ́ rẹ ń lọ sí sáfà àti olùpèsè AI kí a lè rí ìdáhùn. Títẹ̀ pẹ̀lú ohùn àti kíkà sókè ń lo iṣẹ́ ẹ̀rọ rẹ.","Что приложение не делает.":"Ohun tí àpù kì í ṣe.","Не следит за перемещениями, не продаёт и не показывает рекламу, не ставит диагнозов. Счётчики использования считаются только на этом устройстве.":"Kì í tọpinpin ìrìn rẹ, kì í ta dátà, kì í fi ìpolówó hàn, kì í sì ṣe àyẹ̀wò àìsàn. Ìkà ìlò wà lórí ẹ̀rọ yìí nìkan.","Важно.":"Ó ṣe pàtàkì.","Приложение не является медицинским изделием и не заменяет помощь специалиста. Это прототип, и тексты ещё не проверены психологом.":"Àpù yìí kì í ṣe ẹ̀rọ ìṣègùn, kò sì rọ́pò ìrànlọ́wọ́ akọ́ṣẹ́mọṣẹ́. Àpẹẹrẹ àkọ́kọ́ ni, onímọ̀ ìjìnlẹ̀ ọkàn kò tíì ṣàyẹ̀wò àwọn ọ̀rọ̀ inú rẹ̀.","Показать вводную ещё раз":"Tún ìfihàn hàn","Если сейчас очень тяжело или есть риск навредить себе, позвони по номеру 112 или обратись к близкому человеку.":"Tí nǹkan bá le gan-an báyìí tàbí ewu wà pé o lè ṣe ara rẹ léṣe, pe 112 tàbí kàn sí ẹnìkan tó súnmọ́ ọ.","Дневник":"Ìwé ìrántí","Закрыть":"Pa á dé","Маленький шаг":"Ìgbésẹ̀ kékeré","Практика после трудного разговора":"Ìdánrawò lẹ́yìn ìjíròrò tó le","Прежде чем начать":"Kí o tó bẹ̀rẹ̀","Коротко о том, как устроено «Рядом».":"Ní ṣókí, bí Ryadom ṣe ń ṣiṣẹ́.","Что это":"Kí ni","Цифровой помощник для разговора о состоянии, тренировки трудных разговоров и подбора мест. Это не врач и не психолог, диагнозов не ставит и не заменяет специалиста.":"Olùrànlọ́wọ́ oní-nọ́ńbà fún sísọ̀rọ̀ nípa bí o ṣe ń rí, dídánrawò ìjíròrò tó le àti wíwá àwọn ibi. Kì í ṣe dókítà tàbí onímọ̀ ìjìnlẹ̀ ọkàn, kì í ṣe àyẹ̀wò àìsàn, kò sì rọ́pò akọ́ṣẹ́mọṣẹ́.","Где данные":"Ibo ni dátà wà","Дневник, разговоры и «Обо мне» хранятся только на этом устройстве. Ты можешь выгрузить их или удалить всё в разделе «Обо мне».":"Ìwé ìrántí, àwọn ìjíròrò àti “Nípa mi” wà lórí ẹ̀rọ yìí nìkan. O lè gbé wọn jáde tàbí pa gbogbo rẹ̀ rẹ́ nínú “Nípa mi”.","Что уходит наружу":"Ohun tó ń jáde síta","Поиск мест отправляет запрос карте (OpenStreetMap). Если подключён режим с сервером и ИИ, текст сообщения уходит на сервер для ответа. Голосовой ввод использует службы твоего устройства.":"Wíwá ibi ń fi ìbéèrè rẹ ránṣẹ́ sí iṣẹ́ àwòrán ilẹ̀ (OpenStreetMap). Tí a bá so ipò sáfà àti AI pọ̀, ọ̀rọ̀ ìfiránṣẹ́ ń lọ sí sáfà fún ìdáhùn. Títẹ̀ pẹ̀lú ohùn ń lo iṣẹ́ ẹ̀rọ rẹ.","Если тяжело всерьёз":"Tí ó bá le gan-an","При мыслях о вреде себе или другим обратись к человеку рядом или по номеру 112. Приложение подскажет, но срочную помощь оно не заменит.":"Tí o bá ní èrò láti ṣe ara rẹ tàbí àwọn ẹlòmíì léṣe, kàn sí ẹnìkan nítòsí rẹ tàbí pe nọ́ńbà pàjáwìrì (112). Àpù lè fi ọ̀nà hàn, ṣùgbọ́n kò lè rọ́pò ìrànlọ́wọ́ kíákíá.","Понятно, продолжить":"Ó yé mi, máa bá a lọ","Рядом — маленькие шаги к себе":"Ryadom — ìgbésẹ̀ kékeré sí ọ̀dọ̀ ara rẹ","Тревожно":"Àníyàn","Сегодняшняя отметка сохранена. Её можно изменить.":"A ti fi àkọsílẹ̀ òní pamọ́. O lè yí i padà.","дней с отметкой 3–4 из 4":"ọjọ́ tí àmì jẹ́ 3–4 nínú 4","Добавить в любимые":"Fi kún àwọn àyànfẹ́","Любимое место":"Ibi àyànfẹ́","Изменить":"Ṣàtúnṣe","Удалить":"Paárẹ́","Разговоры за этот день":"Àwọn ìjíròrò ọjọ́ yìí","Удалить разговоры за этот день":"Pa àwọn ìjíròrò ọjọ́ yìí rẹ́","Из «Обо мне»:":"Láti “Nípa mi”:","добавлено мной":"èmi ni mo fi kún un","из разговора":"láti inú ìjíròrò","Отметки состояния":"Àkọsílẹ̀ ipò","Отметка о вводном экране":"A ti rí ojú ìfihàn","Разговоры":"Àwọn ìjíròrò","Дневник настроения":"Ìwé ìrántí ìṣesí","Посещённые места":"Àwọn ibi tí a ti lọ","Профиль «Обо мне»":"Profaili “Nípa mi”","Меньше новостей":"Ìròyìn díẹ̀","Если поток новостей усиливает тревогу, отложи его на 15 минут и выбери конкретное время для проверки.":"Bí ìròyìn bá ń mú àníyàn pọ̀ sí i, fi í sílẹ̀ fún ìṣẹ́jú 15 kí o sì yan àkókò pàtó láti wò ó.","Кому можно написать":"Ta ni o lè kọ̀wé sí","Выбери человека, которому можно коротко написать: «Мне тревожно. Можешь побыть на связи?»":"Yan ẹnìkan tí o lè fi ìfiránṣẹ́ kúkúrú ránṣẹ́ sí: “Àníyàn ń bá mi. Ṣé o lè wà pẹ̀lú mi fún ìgbà díẹ̀?”","Назвать чувство":"Dárúkọ ìmọ̀lára","Скажи себе: «Мне сейчас грустно». Не объясняй и не исправляй это чувство в ту же секунду.":"Sọ fún ara rẹ: “Ìbànújẹ́ ń bá mi báyìí.” Má ṣàlàyé tàbí tún ìmọ̀lára náà ṣe lójú ẹsẹ̀.","Мягкий день":"Ọjọ́ jẹ́jẹ́","Составь минимальный план: еда, вода, один обязательный шаг и один посильный источник тепла.":"Ṣe ètò kékeré: oúnjẹ, omi, ìgbésẹ̀ pàtàkì kan àti orísun ìtùnú kan tó ṣeé ṣe.","Память о хорошем":"Rántí nǹkan rere","Вспомни один спокойный момент за последнюю неделю. Запиши детали: место, свет, звук.":"Rántí àsìkò ìdákẹ́jẹ́ kan láàrín ọ̀sẹ̀ tó kọjá. Kọ àlàyé sílẹ̀: ibi, ìmọ́lẹ̀, ohùn.","Тёплый контакт":"Ìfarakanra tó lọ́yàyà","Напиши близкому человеку одну честную фразу о своём состоянии, если хочется быть услышанной или услышанным.":"Tí o bá fẹ́ kí wọ́n gbọ́ tìrẹ, kọ gbólóhùn òtítọ́ kan nípa bí o ṣe ń rí sí ẹnìkan tó súnmọ́ ọ.","Разрешить паузу":"Gbà ara rẹ láàyè láti sinmi","Поставь таймер на пять минут. Можно просто посидеть, не превращая отдых в задачу.":"Ṣètò aago fún ìṣẹ́jú márùn-ún. O lè kàn jókòó, láìsọ ìsinmi di iṣẹ́.","Небольшая забота":"Ìtọ́jú kékeré","Выбери одну бережную вещь: плед, душ, чай или прогулку. Отметь, стало ли хоть немного легче.":"Yan nǹkan ìtùnú kan: aṣọ ìbora, ìwẹ̀, tíì tàbí ìrìn. Kíyèsí bóyá ó rọrùn díẹ̀.","Свет и воздух":"Ìmọ́lẹ̀ àti afẹ́fẹ́","Если удобно, подойди к окну или выйди на несколько минут. Заметь температуру воздуха и положение тела.":"Tí ó bá rọrùn, lọ sí fèrèsé tàbí jáde síta fún ìṣẹ́jú díẹ̀. Kíyèsí bí afẹ́fẹ́ ṣe gbóná tàbí tutù àti bí ara rẹ ṣe wà.","Прежде чем отвечать, отойди от переписки на пару минут. Спроси себя, какой результат нужен от ответа.":"Kí o tó dáhùn, kúrò níbi ìjíròrò fún ìṣẹ́jú díẹ̀. Bi ara rẹ ní èsì wo ni o fẹ́ láti inú ìdáhùn rẹ.","Где злость в теле":"Ibo ni ìbínú wà nínú ara","Заметь, где в теле сейчас напряжение. Расслабь челюсть или плечи, если это приятно, не подавляя чувство.":"Kíyèsí ibi tí ara rẹ ti le báyìí. Tú àgbọ̀n tàbí èjìká rẹ sílẹ̀ tí ó bá dùn mọ́ ọ, láìfi ìmọ̀lára náà pa mọ́.","Черновик без отправки":"Àkọsílẹ̀ tí a kò ní fi ránṣẹ́","Напиши резкий ответ в заметке, которую не отправишь. Затем выдели одну просьбу, которую действительно хочешь донести.":"Kọ ìdáhùn líle sínú àkọsílẹ̀ tí o kò ní fi ránṣẹ́. Lẹ́yìn náà yan ìbéèrè kan tí o fẹ́ fi jíṣẹ́ gan-an.","Отойти от экрана":"Kúrò níwájú ẹ̀rọ","Положи телефон и сделай несколько шагов. Возвращайся к разговору, когда сможешь выбрать тон.":"Gbé fóònù rẹ sílẹ̀ kí o rìn díẹ̀. Padà sí ìjíròrò nígbà tí o bá lè yan ohùn rẹ.","Что задело":"Kí ló dùn ọ́","Раздели на две строки: что произошло и какую важную потребность это затронуло.":"Pín in sí ìlà méjì: ohun tó ṣẹlẹ̀ àti àìní pàtàkì wo ló fọwọ́ kàn.","Безопасная разрядка":"Ìtúsílẹ̀ láìléwu","Сильно прижми стопы к полу на несколько секунд, затем отпусти. Повтори комфортно, без боли.":"Fi ẹsẹ̀ rẹ tẹ ilẹ̀ gidigidi fún ìṣẹ́jú-àáyá díẹ̀, lẹ́yìn náà tú u sílẹ̀. Tún un ṣe pẹ̀lú ìrọ̀rùn, láìsí ìrora.","Право отложить":"Ẹ̀tọ́ láti sún un síwájú","Если нет срочности, назначь время ответа позже. Тебе не обязательно решать конфликт в пике эмоций.":"Tí kò bá pọn dandan kíákíá, yan àkókò láti dáhùn lẹ́yìn náà. O kò ní láti yanjú ìjà nígbà tí ìmọ̀lára bá gbóná jù.","Одна задача":"Iṣẹ́ kan","Выпиши всё, что давит. Обведи одну задачу, которую можно начать за десять минут.":"Kọ gbogbo ohun tó ń wọ̀ ọ́ lọ́rùn sílẹ̀. Fi àyíká yí iṣẹ́ kan tí o lè bẹ̀rẹ̀ láàrín ìṣẹ́jú mẹ́wàá ká.","Пять процентов":"Ìdá márùn-ún nínú ọgọ́rùn-ún","Спроси: что сделает ближайший час на пять процентов легче? Выбери один маленький шаг.":"Béèrè: kí ló máa jẹ́ kí wákàtí tó ń bọ̀ rọrùn ní ìdá márùn-ún? Yan ìgbésẹ̀ kékeré kan.","Снять лишнее":"Yọ àṣejù kúrò","Посмотри на список дел и вычеркни, перенеси или попроси помощи хотя бы с одним пунктом.":"Wo àtòjọ iṣẹ́ rẹ kí o pa ọ̀kan rẹ́, sún un síwájú tàbí béèrè ìrànlọ́wọ́ fún ó kéré tán ọ̀kan.","Перерыв между делами":"Ìsinmi láàrín iṣẹ́","Перед новой задачей сделай паузу: вода, взгляд вдаль, несколько спокойных движений.":"Kí o tó bẹ̀rẹ̀ iṣẹ́ tuntun, sinmi: omi, wíwo ọ̀nà jíjìn, ìṣípòpadà díẹ̀ pẹ̀lú ìfọ̀kànbalẹ̀.","Проверка тела":"Ṣàyẹ̀wò ara","Заметь голод, жажду, усталость и напряжение. Начни с самой простой телесной потребности.":"Kíyèsí ebi, òùngbẹ, àárẹ̀ àti ìlera. Bẹ̀rẹ̀ pẹ̀lú àìní ara tó rọrùn jù.","Достаточно на сегодня":"Ó tó fún òní","Сформулируй критерий «достаточно хорошо» для одной задачи. Остановись, когда он достигнут.":"Ṣàlàyé “ó dára tó” fún iṣẹ́ kan. Dúró nígbà tí o bá dé ibẹ̀.","Попросить ясности":"Béèrè fún àlàyé","Если запрос размытый, уточни срок, приоритет и ожидаемый результат у того, кто его дал.":"Tí ìbéèrè kò bá ṣe kedere, bá ẹni tó fi lélẹ̀ ṣàlàyé àkókò, ohun tó ṣáájú àti èsì tí wọ́n ń retí.","Тихое окно":"Àkókò ìdákẹ́jẹ́","На десять минут отключи необязательные уведомления и займись одним делом.":"Fún ìṣẹ́jú mẹ́wàá, pa àwọn ìkìlọ̀ tí kò pọn dandan kí o ṣe nǹkan kan ṣoṣo.","За некоторое время до сна снизь яркость экрана и выбери спокойное занятие без цели «уснуть немедленно».":"Ní àkókò díẹ̀ ṣáájú oorun, dín ìmọ́lẹ̀ ojú ẹ̀rọ kù kí o yan ìṣe ìdákẹ́jẹ́ láìní àfojúsùn “láti sùn lójú ẹsẹ̀”.","Запиши незавершённые дела и один следующий шаг к каждому. Вернуться к списку можно завтра.":"Kọ àwọn iṣẹ́ tí kò tíì parí sílẹ̀ àti ìgbésẹ̀ tó kàn fún ọ̀kọ̀ọ̀kan. O lè padà sí àtòjọ náà lọ́la.","Комфортная поза":"Ìjókòó tó rọrùn","Устрой тело удобнее и мягко замечай точки опоры. Дыхание оставь естественным.":"Jẹ́ kí ara rẹ rọrùn sí i kí o sì kíyèsí àwọn ibi tó gbé ọ dúró jẹ́jẹ́. Jẹ́ kí èémí rẹ wà bí ó ṣe máa ń rí.","Тихие звуки":"Ohùn jẹ́jẹ́","Прислушайся к трём звукам вокруг. Не оценивай их, просто отмечай появление и исчезновение.":"Fetí sí ohùn mẹ́ta ní àyíká rẹ. Má dájọ́ wọn, kàn kíyèsí bí wọ́n ṣe ń yọ tí wọ́n sì ń pòórá.","Без борьбы со сном":"Láìbá oorun jà","Если не спится, напомни себе: отдых тоже ценен. Выбери спокойное занятие и вернись в постель, когда захочется.":"Tí oorun kò bá kùn ọ́, rán ara rẹ létí: ìsinmi náà ní iye. Yan ìṣe ìdákẹ́jẹ́ kí o sì padà sí ibùsùn nígbà tí o bá fẹ́.","Назначь момент, после которого рабочие сообщения подождут до завтра, если это возможно.":"Tí ó bá ṣeé ṣe, yan àkókò tí ìfiránṣẹ́ iṣẹ́ yóò dúró dé ọ̀la lẹ́yìn rẹ̀.","Мягкое завершение":"Ìparí jẹ́jẹ́","Назови одну вещь, которую удалось сделать сегодня. Даже очень маленькую.":"Dárúkọ nǹkan kan tí o ṣe parí lónìí. Kódà bí ó bá kéré gan-an.","Спокойное утро":"Òwúrọ̀ ìdákẹ́jẹ́","Подготовь одну мелочь для утра: одежду, стакан воды или список первого дела.":"Pèsè nǹkan kékeré kan fún òwúrọ̀: aṣọ, ife omi tàbí àkọsílẹ̀ iṣẹ́ àkọ́kọ́.","Составь фразу: «Когда произошло…, мне было… Мне хотелось бы…».":"Ṣe gbólóhùn kan: “Nígbà tí … ṣẹlẹ̀, mo nímọ̀lára … Mo fẹ́ …”.","Перескажи своими словами, что было услышано от другого человека, и уточни, верно ли это понято.":"Tún ohun tí o gbọ́ lẹ́nu ẹnìkejì sọ pẹ̀lú ọ̀rọ̀ tìrẹ, kí o sì ṣàyẹ̀wò bóyá o lóye rẹ̀ dáadáa.","Попробуй короткий ответ без длинного оправдания: «Сейчас я не могу. Давай обсудим другой вариант».":"Gbìyànjú ìdáhùn kúkúrú láìsí àlàyé gígùn: “Mi ò lè ṣe é báyìí. Ẹ jẹ́ ká jíròrò ọ̀nà míì.”","Раздели лист: «за что отвечаю я» и «за что отвечает другой». Не бери на себя обе стороны.":"Pín ìwé sí méjì: “ohun tí èmi ló kàn” àti “ohun tí ẹnìkejì ló kàn”. Má gbé ẹ̀gbẹ́ méjèèjì.","Пауза в разговоре":"Ìdáduró nínú ìjíròrò","Если разговор накаляется, предложи вернуться к нему в конкретное время после паузы.":"Tí ìjíròrò bá ń gbóná, dábàá láti padà sí i ní àkókò pàtó lẹ́yìn ìsinmi.","Запиши: как я хочу поддерживать контакт и что мне при этом важно решать самостоятельно.":"Kọ ọ́ sílẹ̀: bí mo ṣe fẹ́ máa bá a sọ̀rọ̀ àti ohun tí mo fẹ́ pinnu fúnra mi.","Один вопрос":"Ìbéèrè kan","Вместо догадки спроси: «Что именно ты имеешь в виду?» Дай другому возможность прояснить слова.":"Dípò kí o máa rò ó, béèrè: “Kí ni o ní lọ́kàn gan-an?” Fún ẹnìkejì láǹfààní láti ṣàlàyé.","Если хочется контакта, отправь простое сообщение без ожидания немедленного ответа.":"Tí o bá fẹ́ ìfarakanra, fi ìfiránṣẹ́ rírọrùn ránṣẹ́ láìretí ìdáhùn lójú ẹsẹ̀.","После сложного разговора запиши конкретные задачи и договорённости отдельно от тона и эмоций.":"Lẹ́yìn ìjíròrò tó le, kọ àwọn iṣẹ́ àti àdéhùn pàtó sílẹ̀ lọ́tọ̀ kúrò lára ohùn àti ìmọ̀lára.","Уточнить приоритет":"Ṣàlàyé ohun tó ṣáájú","Спроси, какое из двух дел важнее сегодня. Это превращает неопределённость в выбор.":"Béèrè èwo nínú iṣẹ́ méjèèjì ló ṣe pàtàkì jù lónìí. Èyí ń sọ àìdánilójú di yíyàn.","Составь спокойный черновик: факт, уточняющий вопрос и срок, когда вернёшься с ответом.":"Kọ àkọsílẹ̀ ìdákẹ́jẹ́: òtítọ́ náà, ìbéèrè àlàyé àti ìgbà tí o máa padà pẹ̀lú ìdáhùn.","Раздели обратную связь на полезную часть, спорную часть и форму подачи. Возьми только то, что поможет задаче.":"Pín èsì sí apá tó wúlò, apá tí a lè jiyàn lé lórí àti bí wọ́n ṣe sọ ọ́. Mú èyí tó ń ran iṣẹ́ lọ́wọ́ nìkan.","Маленькая победа":"Ìṣẹ́gun kékeré","Запиши одно завершённое дело за день. Даже если другие ещё ждут.":"Kọ iṣẹ́ kan tí o parí lónìí sílẹ̀. Kódà bí àwọn míì ṣì ń dúró.","Переход домой":"Ìyípadà sí ilé","Закрой рабочий день короткой заметкой о первом шаге на завтра. Переключись на другую деятельность.":"Pa ọjọ́ iṣẹ́ dé pẹ̀lú àkọsílẹ̀ kúkúrú nípa ìgbésẹ̀ àkọ́kọ́ ọ̀la. Yí padà sí ìṣe míì.","Найти союзника":"Wá alátìlẹ́yìn","Подумай, кто может помочь уточнить задачу, дать контекст или поддержать после трудного разговора.":"Ronú nípa ẹni tí ó lè ràn ọ́ lọ́wọ́ láti ṣàlàyé iṣẹ́ náà, fún ọ ní ìtàn àbẹ́lẹ̀ tàbí tì ọ́ lẹ́yìn lẹ́yìn ìjíròrò tó le.","Вернуться к опоре, отделить событие от мыслей и выбрать свой следующий шаг.":"Padà sí ìtìlẹ́yìn, ya ìṣẹ̀lẹ̀ sọ́tọ̀ kúrò lára èrò, kí o sì yan ìgbésẹ̀ rẹ tó kàn.","Проверь сон, еду, воду и паузы. Выбери самое доступное сейчас.":"Ṣàyẹ̀wò oorun, oúnjẹ, omi àti ìsinmi. Yan èyí tó rọrùn jù báyìí.","Сократи задачу до действия на две минуты. Можно остановиться после него.":"Dín iṣẹ́ náà kù sí ìṣe ìṣẹ́jú méjì. O lè dúró lẹ́yìn rẹ̀.","Не объяснять усталость":"Kò pọn dandan láti ṣàlàyé àárẹ̀","Скажи себе: «Сил мало, и я могу выбрать посильный темп». Определи один обязательный пункт.":"Sọ fún ara rẹ: “Agbára mi kéré, mo sì lè yan ìyára tí mo lè fara dà.” Yan nǹkan pàtàkì kan.","Пауза без экрана":"Ìsinmi láìsí ẹ̀rọ","На несколько минут убери экран и посмотри вдаль или закрой глаза, если комфортно.":"Fún ìṣẹ́jú díẹ̀, gbé ẹ̀rọ sí ẹ̀gbẹ́ kan kí o wo ọ̀nà jíjìn tàbí pa ojú dé tí ó bá rọrùn.","Сформулируй конкретную небольшую просьбу человеку, который может помочь.":"Ṣe ìbéèrè kékeré pàtó kan fún ẹni tí ó lè ṣèrànwọ́.","Список «потом»":"Àtòjọ “lẹ́yìn náà”","Запиши необязательные дела в список на другой день, чтобы не держать их в голове.":"Kọ àwọn iṣẹ́ tí kò pọn dandan sínú àtòjọ fún ọjọ́ míì kí o má ṣe gbé wọn sí orí.","Если есть силы и безопасно, пройди несколько минут в удобном темпе. Отдых тоже остаётся вариантом.":"Tí o bá ní agbára tí kò sì léwu, rìn fún ìṣẹ́jú díẹ̀ ní ìyára tó rọrùn. Ìsinmi náà ṣì jẹ́ àṣàyàn.","Один приятный момент":"Àsìkò dídùn kan","Выбери простую вещь, которая не требует подготовки: музыка, вода, окно или тёплый душ.":"Yan nǹkan rírọrùn tí kò nílò ìmúrasílẹ̀: orin, omi, fèrèsé tàbí ìwẹ̀ omi gbígbóná.","Мысль или факт":"Èrò tàbí òtítọ́","Запиши тревожную мысль и рядом — факты за и против. Оставь место для неизвестного.":"Kọ èrò àníyàn náà sílẹ̀, àti lẹ́gbẹ̀ẹ́ rẹ̀ òtítọ́ tó tì í lẹ́yìn àti èyí tó tako ó. Fi àyè sílẹ̀ fún ohun tí a kò mọ̀.","Название мысли":"Dárúkọ èrò","Когда мысль повторяется, произнеси: «У меня появилась мысль, что…». Это создаёт небольшую дистанцию.":"Nígbà tí èrò kan bá ń padà wá, sọ pé: “Mo ní èrò pé…”. Èyí ń dá àlàfo díẹ̀ sílẹ̀.","Круг влияния":"Àyíká ipa","Раздели ситуацию на то, что можешь изменить, на что можешь повлиять и что сейчас вне контроля.":"Pín ipò náà sí ohun tí o lè yí padà, ohun tí o lè nípa lé lórí àti ohun tí kò sí lábẹ́ àkóso rẹ báyìí.","Один следующий шаг":"Ìgbésẹ̀ kan tó kàn","Вместо полного плана выбери действие, которое можно сделать сегодня.":"Dípò ètò pípé, yan ìṣe kan tí o lè ṣe lónìí.","Вернуться к ощущениям":"Padà sí ìmọ̀lára ara","Назови три звука, две видимые детали и одно ощущение от поверхности под рукой.":"Dárúkọ ohùn mẹ́ta, ohun méjì tí o rí àti ìmọ̀lára kan láti ara ohun tí ọwọ́ rẹ wà lórí.","Время для мысли":"Àkókò fún èrò","Если мысль возвращается, запиши её и назначь короткое время позже, когда сможешь к ней вернуться.":"Tí èrò náà bá ń padà wá, kọ ọ́ sílẹ̀ kí o sì yan àkókò kúkúrú lẹ́yìn náà láti padà sí i.","Два объяснения":"Àlàyé méjì","Найди ещё одно возможное объяснение событию, кроме самого пугающего. Не обязательно верить в него сразу.":"Wá àlàyé míì tó ṣeé ṣe fún ohun tó ṣẹlẹ̀, yàtọ̀ sí èyí tó bani lẹ́rù jù. O kò ní láti gbà á gbọ́ lójú ẹsẹ̀.","Спросить, а не угадать":"Béèrè dípò kí o máa ronú","Если мысль касается намерений другого, сформулируй вопрос, который поможет прояснить ситуацию.":"Tí èrò náà bá jẹ mọ́ èrò ọkàn ẹlòmíì, ṣe ìbéèrè tí yóò ràn ọ́ lọ́wọ́ láti ṣàlàyé ipò náà.","Что уже помогает":"Ohun tó ti ń ṣèrànwọ́ tẹ́lẹ̀","Заметь, что сейчас поддерживает тебя: человек, место, движение или привычка. Сохрани это в памяти.":"Kíyèsí ohun tó ń tì ọ́ lẹ́yìn báyìí: ènìyàn, ibi, ìṣípòpadà tàbí àṣà. Fi í sọ́kàn.","Поблагодарить себя":"Dúpẹ́ lọ́wọ́ ara rẹ","Назови один свой шаг сегодня без оценки его масштаба.":"Dárúkọ ìgbésẹ̀ kan tí o gbé lónìí láìdíwọ̀n bí ó ṣe tóbi tó.","Фото момента":"Àwòrán àsìkò","Опиши словами спокойный момент: цвет, звук, температуру и чувство в теле.":"Ṣàpèjúwe àsìkò ìdákẹ́jẹ́ kan pẹ̀lú ọ̀rọ̀: àwọ̀, ohùn, ìgbóná àti ìmọ̀lára nínú ara.","Забота на завтра":"Ìtọ́jú fún ọ̀la","Выбери одну маленькую вещь, которую хочется повторить завтра.":"Yan nǹkan kékeré kan tí o fẹ́ tún ṣe lọ́la.","Делиться хорошим":"Pín ohun rere","Если хочется, расскажи кому-то о приятном моменте, не превращая это в отчёт.":"Tí o bá fẹ́, sọ fún ẹnìkan nípa àsìkò dídùn kan láìsọ ọ́ di ìròyìn.","Просто побыть":"Kàn wà","Разреши себе несколько минут ничего не улучшать. Замечай, что уже есть.":"Fún ara rẹ ní ìṣẹ́jú díẹ̀ láìtún ohunkóhun ṣe. Kíyèsí ohun tó ti wà níbẹ̀.","Мягкий план":"Ètò jẹ́jẹ́","Пока спокойно, запиши, что обычно помогает в более сложные дни.":"Nígbà tí ara rẹ balẹ̀, kọ ohun tó máa ń ṣèrànwọ́ ní àwọn ọjọ́ tó le sílẹ̀.","Свободное время":"Àkókò ọ̀fẹ́","Оставь в дне небольшой отрезок без обязательного результата.":"Fi àkókò kékeré sílẹ̀ nínú ọjọ́ láìsí èsì tí a gbọ́dọ̀ rí.","2 минуты":"Ìṣẹ́jú 2","Дыши комфортно, без задержки и усилия. На вдохе круг расширяется, на выдохе сужается. Если кружится голова, остановись и дыши обычно.":"Mí pẹ̀lú ìrọ̀rùn, láìdá èémí dúró tàbí fipá. Àyíká máa ń gbòòrò nígbà tí o bá mí wọlé, á sì kéré nígbà tí o bá mí jáde. Tí orí bá ń yí ọ, dúró kí o mí bí ó ṣe máa ń rí.","Начать дыхание":"Bẹ̀rẹ̀ mímí","Закончить":"Parí","Дыши в своём ритме":"Mí ní ìlù tìrẹ","1 минута":"Ìṣẹ́jú 1","Назови 5 вещей, которые видишь; 4, которые ощущаешь телом; 3 звука. Не спеши. Сейчас ты здесь.":"Dárúkọ nǹkan 5 tí o rí, 4 tí ara rẹ ń rí, ohùn 3. Má yára. Báyìí, o wà níbí.","Представь между собой и резкими словами прозрачное стекло. Слова остаются по ту сторону. Спроси себя: что из сказанного относится к задаче, а что говорит о состоянии другого человека?":"Fojú inú wo gíláàsì tó mọ́ láàrín ìwọ àti ọ̀rọ̀ líle náà. Ọ̀rọ̀ náà wà ní òdìkejì. Bi ara rẹ: èwo nínú ohun tí wọ́n sọ ló jẹ mọ́ iṣẹ́, èwo ló ń sọ nípa ipò ẹnìkejì?","3 минуты":"Ìṣẹ́jú 3","Запиши три короткие строки: 1) Что произошло? 2) Что я сейчас чувствую? 3) Какой один небольшой шаг мне доступен? Не нужно искать идеальное решение.":"Kọ ìlà kúkúrú mẹ́ta: 1) Kí ló ṣẹlẹ̀? 2) Kí ni mo ń rí lára báyìí? 3) Ìgbésẹ̀ kékeré wo ni mo lè gbé? O kò nílò ojútùú pípé.","Если бы близкий человек оказался на твоём месте, какие слова поддержки нашлись бы для него? Попробуй обратиться с этой же фразой к себе.":"Tí ẹnìkan tó súnmọ́ ọ bá wà ní ipò rẹ, ọ̀rọ̀ ìtìlẹ́yìn wo ni o máa sọ fún un? Gbìyànjú láti sọ irú ọ̀rọ̀ bẹ́ẹ̀ fún ara rẹ.","Если есть возможность, встань, сделай несколько спокойных шагов и выпей воды. Посмотри в окно или выйди на воздух. Потом проверь, изменилось ли что-то хотя бы на один процент.":"Tí ó bá ṣeé ṣe, dìde, rìn díẹ̀ pẹ̀lú ìfọ̀kànbalẹ̀ kí o sì mu omi. Wo fèrèsé tàbí jáde síta. Lẹ́yìn náà ṣàyẹ̀wò bóyá nǹkan yí padà, kódà ní ìdá kan nínú ọgọ́rùn-ún.","1 мин":"Ìṣẹ́jú 1","2 мин":"Ìṣẹ́jú 2","3 мин":"Ìṣẹ́jú 3","5 мин":"Ìṣẹ́jú 5","10 мин":"Ìṣẹ́jú 10","✦ РЯДОМ · ПРАКТИКА":"✦ RYADOM · ÌDÁNRAWÒ","ПЕРЕД НАЧАЛОМ":"KÍ A TÓ BẸ̀RẸ̀","Что осталось после разговора?":"Kí ló kù lẹ́yìn ìjíròrò náà?","Нам не нужно сейчас разбирать всё сразу. Отметь, с кем был разговор и насколько сильно он задел тебя в данный момент.":"A kò nílò láti tú gbogbo rẹ̀ palẹ̀ báyìí. Sàmì sí ẹni tí ìjíròrò náà wà pẹ̀lú àti bí ó ṣe dùn ọ́ tó báyìí.","На работе":"Níbi iṣẹ́","С близким":"Pẹ̀lú ẹnìkan tó súnmọ́ mi","В другой ситуации":"Nínú ipò míì","Насколько сильно задело сейчас?":"Báwo ló ṣe dùn ọ́ tó báyìí?","Немного":"Díẹ̀","Очень сильно":"Gan-an","Если сейчас небезопасно или ситуация продолжается, сначала позаботься о своей безопасности и обратись к человеку рядом. Практику можно закрыть в любой момент.":"Tí kò bá séwu báyìí tàbí ipò náà ṣì ń lọ, kọ́kọ́ bójú tó ààbò rẹ kí o sì kàn sí ẹnìkan nítòsí. O lè pa ìdánrawò dé nígbàkigbà.","Начать →":"Bẹ̀rẹ̀ →","01 · ВЕРНУТЬСЯ В МОМЕНТ":"01 · PADÀ SÍ ÀSÌKÒ YÌÍ","Сейчас ты здесь":"Báyìí o wà níbí","Не нужно менять дыхание. Найди глазами одну вещь вокруг, услышь один звук и почувствуй опору под ногами или телом. Нажми на то, что удалось заметить.":"Kò pọn dandan láti yí èémí padà. Fi ojú wá nǹkan kan ní àyíká rẹ, gbọ́ ohùn kan, kí o sì nímọ̀lára ìtìlẹ́yìn lábẹ́ ẹsẹ̀ tàbí ara rẹ. Tẹ ohun tí o kíyèsí.","здесь":"níbí","и сейчас":"àti báyìí","○ Вижу предмет":"○ Mo rí nǹkan kan","○ Слышу звук":"○ Mo gbọ́ ohùn kan","○ Чувствую опору":"○ Mo nímọ̀lára ìtìlẹ́yìn","Можно просто прочитать и двигаться дальше. Если внимание к телу неприятно, пропусти этот шаг.":"O lè kàn kà á kí o máa bá a lọ. Tí kíkíyèsí ara kò bá dùn mọ́ ọ, fo ìgbésẹ̀ yìí.","Назад":"Padà","Продолжить →":"Máa bá a lọ →","✓ Вижу предмет":"✓ Mo rí nǹkan kan","✓ Слышу звук":"✓ Mo gbọ́ ohùn kan","✓ Чувствую опору":"✓ Mo nímọ̀lára ìtìlẹ́yìn","02 · ОТДЕЛИТЬ СОБЫТИЕ ОТ МЫСЛИ":"02 · YA ÌṢẸ̀LẸ̀ SỌ́TỌ̀ KÚRÒ NÍNÚ ÈRÒ","Две разные вещи":"Nǹkan méjì tó yàtọ̀","Попробуй разделить то, что произошло, и то, что подумалось после. Это не проверка правильности твоих чувств. Поля можно оставить пустыми.":"Gbìyànjú láti ya ohun tó ṣẹlẹ̀ sọ́tọ̀ kúrò lára ohun tí o rò lẹ́yìn náà. Kì í ṣe ìdánwò bóyá ìmọ̀lára rẹ tọ̀nà. O lè fi àwọn àyè sílẹ̀ ní òfo.","Что было сказано или сделано?":"Kí ni wọ́n sọ tàbí ṣe?","Какая мысль у меня об этом появилась?":"Èrò wo ló wá sí mi lọ́kàn nípa rẹ̀?","Чувства реальны. Мысль о себе — не всегда факт. Необязательно находить объяснение прямо сейчас.":"Ìmọ̀lára jẹ́ òtítọ́. Èrò nípa ara rẹ kì í ṣe òtítọ́ nígbà gbogbo. O kò ní láti rí àlàyé báyìí.","03 · ОДИН СЛЕДУЮЩИЙ ШАГ":"03 · ÌGBÉSẸ̀ KAN TÓ KÀN","Что сейчас подойдёт?":"Kí ló máa bá ìsinsìnyí mu?","Выбери действие, которое зависит от тебя. Оно может быть маленьким и не обязано решать весь конфликт.":"Yan ìṣe kan tó dá lórí rẹ. Ó lè kéré, kò sì ní láti yanjú gbogbo ìjà náà.","Дать себе паузу":"Fún ara rẹ ní ìdáduró","Можно ничего не отправлять прямо сейчас. Назначь момент, когда снова посмотришь на ситуацию.":"O kò ní láti fi ohunkóhun ránṣẹ́ báyìí. Yan àkókò tí o máa tún wo ipò náà.","Уточнить задачу":"Ṣàlàyé iṣẹ́ náà","Этот вариант подходит, если за неприятным тоном была конкретная рабочая задача.":"Àṣàyàn yìí bá a mu tí iṣẹ́ pàtó kan bá wà lẹ́yìn ohùn tí kò dùn náà.","Обозначить границу":"Fi ààlà lélẹ̀","Подстрой слова под себя. Ты выбираешь время и безопасный способ разговора.":"Ṣe àwọn ọ̀rọ̀ náà bí ó ṣe bá ọ mu. Ìwọ ni o yan àkókò àti ọ̀nà ààbò láti sọ̀rọ̀.","Попросить поддержки":"Béèrè ìtìlẹ́yìn","Поддержка может быть короткой: сообщение, звонок или совместная прогулка.":"Ìtìlẹ́yìn lè kúrú: ìfiránṣẹ́, ìpè tàbí ìrìn papọ̀.","Как сейчас, по той же шкале?":"Báwo ló ṣe rí báyìí, lórí ìwọ̀n kan náà?","Не хочу оценивать":"Mi ò fẹ́ díwọ̀n rẹ̀","Завершить и сохранить →":"Parí kí o sì fi pamọ́ →","ВОЗМОЖНАЯ ФРАЗА":"GBÓLÓHÙN TÓ ṢEÉ ṢE","«Я вернусь к разговору позже. Сейчас мне нужно немного времени».":"“Màá padà sí ìjíròrò yìí lẹ́yìn náà. Mo nílò àkókò díẹ̀ báyìí.”","Готово":"Ó ti parí","ТВОЙ МАЛЕНЬКИЙ ШАГ":"ÌGBÉSẸ̀ KÉKERÉ RẸ","Можно остановиться здесь":"O lè dúró síbí","Состояние замечено, действие выбрано. Не нужно заставлять себя чувствовать лучше.":"A ti kíyèsí ipò náà, a sì ti yan ìṣe. O kò ní láti fipá mú ara rẹ láti rí dáadáa.","ЧТО ВЫБРАНО":"OHUN TÍ A YAN","Состояние пока не изменилось. Ты всё равно можешь остановиться или выбрать поддержку.":"Ipò náà kò tíì yí padà. O ṣì lè dúró tàbí yan ìtìlẹ́yìn.","В дневник сохранены только тема, выбранный шаг и твоя оценка результата. Написанные тобой фразы не сохранялись.":"Kókó ọ̀rọ̀, ìgbésẹ̀ tí o yàn àti ìdíwọ̀n rẹ nìkan ni a fi pamọ́ sínú ìwé ìrántí. A kò fi àwọn gbólóhùn tí o kọ pamọ́.","Вернуться в приложение":"Padà sí àpù","Добавить место":"Fi ibi kún un","Название *":"Orúkọ *","Например, любимая кофейня":"àpẹẹrẹ, ilé kọfí tí o fẹ́ràn","Район или адрес":"Àdúgbò tàbí àdírẹ́sì","Необязательно":"Kò pọn dandan","Примерное время":"Àkókò ní àyíká","Что это за место?":"Irú ibi wo ni?","Кафе":"Ilé kọfí","Парк":"Ọgbà","Прогулка":"Ìrìn","Культура":"Àṣà","Другое":"Òmíràn","Как тебе там было?":"Báwo ló ṣe rí lára rẹ níbẹ̀?","Спокойно":"Ìdákẹ́jẹ́","Радостно":"Ayọ̀","Уютно":"Ìtura","Грустно":"Ìbànújẹ́","По-разному":"Oríṣiríṣi","Что запомнилось?":"Kí ló dúró sí ọkàn rẹ?","Отмена":"Fagilé","Сохранить место":"Fi ibi pamọ́","Удалить разговоры, отметки, места и любимые места из дневника на этом устройстве? Игровой прогресс останется.":"Ṣé kí a pa àwọn ìjíròrò, àkọsílẹ̀, àwọn ibi àti àwọn àyànfẹ́ rẹ́ kúrò nínú ìwé ìrántí ẹ̀rọ yìí? Ìlọsíwájú eré yóò wà.","{x}: {0}":"{x}: {0}","Сообщений в разговоре":"Àwọn ìfiránṣẹ́ nínú ìjíròrò","Практик открыто":"Àwọn ìdánrawò tí a ṣí","Тренажёров начато":"Àwọn ìdánrawò tí a bẹ̀rẹ̀","Тренажёров пройдено":"Àwọn ìdánrawò tí a parí","Открытий «Практик»":"Ìṣí “Ìdánrawò”","Открытий «Игр»":"Ìṣí “Eré”","Открытий «Мест»":"Ìṣí “Àwọn ibi”","Открытий дневника":"Ìṣí ìwé ìrántí","{x}: {y} {0} из {1}":"{x}: {y} {0} nínú {1}","тревога":"àníyàn","грусть":"ìbànújẹ́","беспокойство":"àìbalẹ̀ ọkàn","спокойствие":"ìfọ̀kànbalẹ̀","Да, удалить":"Bẹ́ẹ̀ni, pa á rẹ́","Неспешная прогулка, книга или чашка чая. Выбирай только то, на что есть силы.":"Ìrìn pẹ̀lẹ́, ìwé kan tàbí ife tíì kan. Yan ohun tí o ní agbára fún nìkan.","Место, где можно сменить обстановку. Тишину и отсутствие людей лучше проверить самому.":"Ibi tí o lè yí àyíká padà. Ṣàyẹ̀wò ìdákẹ́jẹ́ẹ́ àti èrò fúnra rẹ.","Прогулка, вид на город или уютное место для встречи.":"Ìrìn, ìwòye ìlú tàbí ibi tó dùn láti pàdé.","Места, где можно гулять, смотреть кино или быть среди людей.":"Àwọn ibi láti rìn, wo fíìmù tàbí wà láàrin ènìyàn.","Пространства для неторопливого времени.":"Àwọn ibi fún àkókò láìsí ìkánjú.","Музей, галерея или книжное место могут дать новую мысль.":"Ilé ọnà, ibi àwòrán tàbí ilé ìwé lè mú èrò tuntun wá.","Поблизости и без большого плана: кофе или короткая прогулка.":"Nítòsí, láìsí ètò ńlá: kọfí tàbí ìrìn kúkúrú.","Места для встречи. Загруженность и атмосферу уточни перед поездкой.":"Àwọn ibi ìpàdé. Ṣàyẹ̀wò èrò àti àyíká kí o tó lọ.","Будут удалены дневник, разговоры, «Обо мне», места и прогресс игр на этом устройстве. Вернуть их будет нельзя, если нет копии.":"Ìwé ìrántí, ìjíròrò, «Nípa mi», àwọn ibi àti ìlọsíwájú eré lórí ẹ̀rọ yìí ni a ó pa rẹ́. Kò ṣeé dá padà láìsí ẹ̀dà.","Да, удалить всё":"Bẹ́ẹ̀ni, pa gbogbo rẹ̀ rẹ́","Удалить все записи профиля? Вернуть их будет нельзя.":"Pa gbogbo àkọsílẹ̀ profaili rẹ́? Kò ṣeé dá padà.","Да, стереть":"Bẹ́ẹ̀ni, nù ú","После нескольких отметок здесь появится короткое наблюдение о твоём состоянии.":"Lẹ́yìn àmì díẹ̀, àkíyèsí kúkúrú nípa ipò rẹ yóò hàn níbí.","Здесь появятся твои отметки после первого разговора.":"Àwọn àmì rẹ yóò hàn níbí lẹ́yìn ìjíròrò àkọ́kọ́.","Разговор с «Рядом»":"Ìjíròrò pẹ̀lú Ryadom","Например: трудный разговор, прогулка или приятный момент":"Fún àpẹẹrẹ: ìjíròrò tó le, ìrìn tàbí àkókò dídùn","Интерактивный прототип приложения ежедневной эмоциональной поддержки.":"Àpẹẹrẹ ìbánisọ̀rọ̀ ti áàpù àtìlẹ́yìn ìmọ̀lára ojoojúmọ́.","Твои мысли остаются только на этом экране и не сохраняются":"Èrò rẹ wà lórí ojú-ìwé yìí nìkan, a kò fi pamọ́","Заметка":"Àkọsílẹ̀","Как ты сейчас после этого шага?":"Báwo ni o ṣe wà báyìí lẹ́yìn ìgbésẹ̀ yìí?","Чуть легче":"Ó fúyẹ́ díẹ̀","Пока так же":"Ó ṣì rí bẹ́ẹ̀","Стало хуже":"Ó burú sí i","День":"Ọjọ́","Отмечено состояний: {0}. График показывает только твои ответы, без оценок и диагнозов.":"Ipò tí a sàmì sí: {0}. Àwòrán yìí ń fi ìdáhùn rẹ nìkan hàn, láìsí ìdíyelé tàbí àyẹ̀wò àrùn.","Одна короткая отметка в день — уже начало.":"Àmì kúkúrú kan lójoojúmọ́ ti jẹ́ ìbẹ̀rẹ̀ tẹ́lẹ̀.","Удалить все отметки из этого браузера?":"Pa gbogbo àmì rẹ́ kúrò nínú aṣàwákiri yìí?","В {0} из {1} отмеченных дней тревога была сильной. Можно посмотреть, что происходило в эти дни, и обратиться за поддержкой, если это мешает жить.":"Ní ọjọ́ {0} nínú {1} tí a sàmì sí, àníyàn le. O lè wo ohun tó ṣẹlẹ̀ ní ọjọ́ wọ̀nyẹn, kí o sì wá ìrànlọ́wọ́ bí ó bá ń dí ìgbésí ayé rẹ lọ́wọ́.","За выбранный период сильная тревога отмечалась в {0} из {1} дней. Посмотри, какие занятия и разговоры помогали тебе чувствовать себя спокойнее.":"Ní àkókò tí a yàn, a sàmì àníyàn líle ní ọjọ́ {0} nínú {1}. Wo àwọn iṣẹ́ àti ìjíròrò tó ràn ọ́ lọ́wọ́ láti balẹ̀.","На этот день нет записи. Пустая клетка ничего не говорит о том, каким был день.":"Kò sí àkọsílẹ̀ fún ọjọ́ yìí. Àpótí òfìfo kò sọ nǹkan kan nípa bí ọjọ́ náà ṣe rí.","чуть легче":"ó fúyẹ́ díẹ̀","без изменений":"kò yí padà","стало хуже":"ó burú sí i","без оценки":"a kò dìíyelé","Удалить разговоры, отметки и заметки дневника из этого браузера? Игровой прогресс останется.":"Pa ìjíròrò, àmì àti àkọsílẹ̀ ìwé ìrántí rẹ́ kúrò nínú aṣàwákiri yìí? Ìlọsíwájú eré yóò wà.","Скоро":"Láìpẹ́","Ничего не найдено. Попробуй другое слово или состояние.":"Kò rí nǹkan kan. Gbìyànjú ọ̀rọ̀ tàbí ipò mìíràn.","Поддержка":"Àtìlẹ́yìn","Мне очень жаль, что сейчас так тяжело. Если есть риск причинить себе вред прямо сейчас, позови человека рядом и обратись за срочной помощью по местному экстренному номеру. Ты можешь сказать: «Мне сейчас небезопасно оставаться одной или одному. Побудь со мной и помоги получить помощь».":"Ó dùn mí gan-an pé ó le báyìí. Bí ewu bá wà pé o lè pa ara rẹ lára báyìí, pe ẹnì kan nítòsí kí o sì wá ìrànlọ́wọ́ kíákíá nípasẹ̀ nọ́mbà pàjáwìrì àdúgbò rẹ. O lè sọ pé: «Kò ní ààbò fún mi láti dá wà báyìí. Dúró pẹ̀lú mi kí o sì ràn mí lọ́wọ́ láti rí ìrànlọ́wọ́.»","Показать фразу для близкого":"Fi ọ̀rọ̀ hàn fún ẹni tó sún mọ́ ọ","Можно отправить: «Мне сейчас очень тяжело. Пожалуйста, позвони мне или побудь со мной. Помоги обратиться за помощью».":"O lè fi ránṣẹ́: «Ó le fún mi gan-an báyìí. Jọ̀ọ́ pè mí tàbí dúró pẹ̀lú mi. Ràn mí lọ́wọ́ láti wá ìrànlọ́wọ́.»","Хорошо, что об этом сказано вслух. Если состояние изменится, обратись к человеку рядом или за срочной помощью.":"Ó dára pé a sọ èyí jáde. Bí ipò rẹ bá yí padà, kàn sí ẹnì kan nítòsí tàbí wá ìrànlọ́wọ́ kíákíá.","Начнём новый разговор. Как ты сейчас?":"Ẹ jẹ́ ká bẹ̀rẹ̀ ìjíròrò tuntun. Báwo ni o ṣe wà báyìí?","Рада это слышать. Что сегодня помогло тебе чувствовать себя так?":"Inú mi dùn láti gbọ́ èyí. Kí ló ràn ọ́ lọ́wọ́ láti ní ìmọ̀lára báyìí lónìí?","Спасибо, что об этом сказано. Что произошло или когда это ощущение появилось? Можно ответить своими словами.":"O ṣé tí o sọ èyí. Kí ló ṣẹlẹ̀, tàbí ìgbà wo ni ìmọ̀lára yìí bẹ̀rẹ̀? O lè dáhùn ní ọ̀rọ̀ ara rẹ.","Близкие":"Àwọn olólùfẹ́","Не знаю, почему":"N kò mọ ìdí","Понимаю. Насколько сильно это сейчас ощущается — от 1 до 4? Если сложно оценить, можно пропустить.":"Ó yé mi. Báwo ló ṣe le tó báyìí, láti 1 sí 4? Bí ó bá ṣòro láti dìíyelé, o lè fò ó.","1 · немного":"1 · díẹ̀","2 · заметно":"2 · ó hàn gbangba","3 · сильно":"3 · gidigbí","4 · очень сильно":"4 · gidigbí púpọ̀","Пропустить":"Fò ó","Что хочется сделать с этим ощущением?":"Kí lo fẹ́ ṣe pẹ̀lú ìmọ̀lára yìí?","Что сейчас было бы нужнее: немного успокоиться, разобраться в ситуации, просто выговориться или отдохнуть?":"Kí ló wúlò jù báyìí: kí o balẹ̀ díẹ̀, kí o yé ipò náà, kí o kàn sọ̀rọ̀ jáde, tàbí kí o sinmi?","Успокоиться":"Láti balẹ̀","Разобраться":"Láti yé mi","Выговориться":"Láti sọ̀rọ̀ jáde","Отдохнуть":"Láti sinmi","Я слушаю. Расскажи, что было самым неприятным или важным в этом моменте.":"Mo ń gbọ́. Sọ fún mi ohun tó burú jù tàbí tó ṣe pàtàkì jù ní àkókò yẹn.","Похоже, это действительно задело. Что хотелось бы получить сейчас? Можно выбрать маленький шаг, а можно продолжить разговор.":"Ó dàbí pé èyí dùn ọ́ gan-an. Kí lo fẹ́ báyìí? O lè yan ìgbésẹ̀ kékeré tàbí kí o máa bá ọ̀rọ̀ lọ.","Рассказать ещё":"Sọ sí i","Закончить пока":"Dúró ná","Я рядом. Что ещё важно сказать?":"Mo wà níbí. Kí ni ohun mìíràn tó ṣe pàtàkì láti sọ?","Спасибо, что поделилась или поделился. Можно вернуться, когда захочешь.":"O ṣé tí o pín in. O lè padà wá nígbàkígbà tí o bá fẹ́.","Новый разговор":"Ìjíròrò tuntun","Я слушаю. Что хочется рассказать?":"Mo ń gbọ́. Kí lo fẹ́ sọ?","Спасибо за разговор. Вернись, когда захочешь.":"O ṣé fún ìjíròrò náà. Padà wá nígbàkígbà tí o bá fẹ́.","Слышу тебя. Что из этого сейчас важнее всего? Можешь рассказать ещё или выбрать шаг.":"Mo gbọ́ ọ. Kí ló ṣe pàtàkì jù nínú èyí báyìí? O lè sọ sí i tàbí yan ìgbésẹ̀ kan.","Рада, что стало хоть немного легче. Что именно помогло?":"Inú mi dùn pé ó fúyẹ́ díẹ̀. Kí ni gangan ló ṣèrànwọ́?","Жаль, что стало хуже. Остановимся с этой практикой. Сейчас лучше выбрать более мягкую поддержку или обратиться к близкому человеку.":"Ó dùn mí pé ó burú sí i. Ẹ jẹ́ ká dá ìdánrawò yìí dúró. Ó sàn báyìí láti yan àtìlẹ́yìn tó rọ̀ jù tàbí kàn sí ẹni tó sún mọ́ ọ.","Хорошо, что это получилось заметить. Можно попробовать другой шаг или просто остановиться.":"Ó dára pé o kíyèsí èyí. O lè gbìyànjú ìgbésẹ̀ mìíràn tàbí kí o kàn dúró.","Расскажу ещё":"Màá sọ sí i","Я слушаю. Что сейчас на первом плане?":"Mo ń gbọ́. Kí ló wà lọ́kàn rẹ jù báyìí?","Спасибо за разговор. Береги свой темп.":"O ṣé fún ìjíròrò náà. Máa tọ́jú ìyára ara rẹ.","Если захочешь, начнём новый разговор.":"Bí o bá fẹ́, a ó bẹ̀rẹ̀ ìjíròrò tuntun.","Тогда начнём с очень маленькой паузы.":"Nígbà náà ẹ jẹ́ ká bẹ̀rẹ̀ pẹ̀lú ìdádúró kékeré gan-an.","Давай отделим то, что произошло, от догадок.":"Ẹ jẹ́ ká ya ohun tó ṣẹlẹ̀ sọ́tọ̀ kúrò lára àròjinlẹ̀.","Можно попробовать один из этих шагов. Выбирай только то, что подходит.":"O lè gbìyànjú ọ̀kan nínú àwọn ìgbésẹ̀ wọ̀nyí. Yan èyí tó bá ọ mu nìkan.","Хочу рассказать ещё":"Mo fẹ́ sọ sí i","Пока достаточно":"Ó tó ná","Как ты после этого шага?":"Báwo ni o ṣe wà lẹ́yìn ìgbésẹ̀ yìí?","Голосовой ввод не поддерживается этим браузером":"Aṣàwákiri yìí kò ṣe àtìlẹ́yìn fún ìtẹ̀wọlé ohùn","Голосовой ввод недоступен в этом браузере. Можно писать текстом.":"Ìtẹ̀wọlé ohùn kò sí nínú aṣàwákiri yìí. O lè kọ ọ́.","Распознавание голоса выполняет устройство и может передавать запись его сервису. Продолжить?":"Ẹ̀rọ rẹ ló ń dá ohùn mọ̀, ó sì lè fi gbígbàsílẹ̀ ránṣẹ́ sí iṣẹ́ rẹ̀. Ṣé kí a tẹ̀síwájú?","Да, включить":"Bẹ́ẹ̀ni, tan án","Остановить запись":"Dá gbígbàsílẹ̀ dúró","Слушаю. Фраза появится в поле ввода — проверь её перед отправкой.":"Mo ń gbọ́. Gbólóhùn náà yóò hàn nínú àpótí ìtẹ̀wọlé — ṣàyẹ̀wò rẹ̀ kí o tó fi ránṣẹ́.","Проверь текст и нажми отправить, когда текст устроит.":"Ṣàyẹ̀wò ọ̀rọ̀ náà kí o tẹ fi ránṣẹ́ nígbà tó bá dára.","Нет доступа к микрофону. Можно продолжить текстом.":"Kò sí àyè sí makirofóònù. O lè tẹ̀síwájú nípa kíkọ.","Не удалось распознать речь. Попробуй ещё раз или напиши текстом.":"Kò lè dá ọ̀rọ̀ mọ̀. Gbìyànjú lẹ́ẹ̀kan sí i tàbí kọ ọ́.","Не удалось включить микрофон.":"Kò lè tan makirofóònù.","4–6 минут":"Ìṣẹ́jú 4–6","Небольшая самостоятельная практика после неприятного разговора.":"Ìdánrawò kékeré fúnra rẹ lẹ́yìn ìjíròrò tí kò dùn.","После трудного разговора · 4–6 минут":"Lẹ́yìn ìjíròrò tó le · ìṣẹ́jú 4–6","«Помоги понять: какой результат ожидается и к какому сроку?»":"«Ràn mí lọ́wọ́ láti lóye: èsì wo ni a ń retí, àti nígbà wo?»","«Мне важно обсудить вопрос, когда мы можем говорить спокойно».":"«Ó ṣe pàtàkì fún mi láti jíròrò èyí nígbà tí a bá lè sọ̀rọ̀ ní ìbàlẹ̀.»","«У меня был трудный разговор. Можешь немного побыть со мной на связи?»":"«Mo ní ìjíròrò tó le. Ṣé o lè wà pẹ̀lú mi fún ìgbà díẹ̀?»","Шаг {0} из 4":"Ìgbésẹ̀ {0} nínú 4","Пауза":"Ìdádúró","Результат не оценён. Это тоже нормально.":"A kò dìíyelé èsì náà. Ìyẹn náà dára.","Отмечено небольшое облегчение.":"A sàmì ìtura díẹ̀.","Стало тяжелее. Эту практику можно оставить и обратиться к человеку, которому доверяешь.":"Ó ti le sí i. O lè fi ìdánrawò yìí sílẹ̀ kí o sì kàn sí ẹni tí o gbẹ́kẹ̀lé.","Вижу предмет":"Mo rí nǹkan kan","Слышу звук":"Mo gbọ́ ìró kan","Чувствую опору":"Mo ní ìmọ̀lára ìtìlẹ́yìn","Например: «Руководитель повысил голос и попросил переделать отчёт»":"Fún àpẹẹrẹ: «Ọ̀gá gbé ohùn sókè ó sì ní kí n tún ìròyìn náà ṣe»","Например: «Наверное, я ни на что не способна или не способен»":"Fún àpẹẹrẹ: «Bóyá n kò lè ṣe nǹkan kan»","Практика пройдена в твоём темпе. Хочешь рассказать ещё или закончить?":"O parí ìdánrawò ní ìyára ara rẹ. Ṣé o fẹ́ sọ sí i tàbí parí?","Отмечено, что стало немного легче. Хочешь остановиться или рассказать, какой шаг оказался выбран?":"A sàmì pé ó fúyẹ́ díẹ̀. Ṣé o fẹ́ dúró, tàbí sọ ìgbésẹ̀ tí o yàn?","Похоже, сейчас стало тяжелее. Остановимся. Можно обратиться к человеку рядом или выбрать другую поддержку.":"Ó dàbí pé ó ti le sí i. Ẹ jẹ́ ká dúró. O lè kàn sí ẹnì kan nítòsí tàbí yan àtìlẹ́yìn mìíràn.","Спасибо за оценку результата. Хочешь рассказать ещё или закончить?":"O ṣé fún ìdíyelé èsì náà. Ṣé o fẹ́ sọ sí i tàbí parí?","тревожно":"àníyàn","тяжело":"ó wúwo","злюсь":"ìbínú","нормально":"ó dára","хорошо":"dáadáa","✓ Сделано":"✓ Ó ti parí","Скопировано":"A ti dà á kọ","Не удалось":"Kò ṣeé ṣe","Запись о тебе сейчас выключена. Включить её можно в разделе «Обо мне».":"Àkọsílẹ̀ nípa rẹ ti wà ní pípa báyìí. O lè tan wọ́n ní «Nípa mi».","Такая запись уже есть или список полон.":"Àkọsílẹ̀ yìí ti wà tẹ́lẹ̀ tàbí àtòkọ ti kún.","Избранные места":"Àwọn ibi àyànfẹ́","Найденные места":"Àwọn ibi tí a rí","Выбранный город":"Ìlú tí a yàn","Счётчики на этом устройстве":"Àwọn òǹkà lórí ẹ̀rọ yìí","Цепочки практик":"Ẹ̀wọ̀n ìdánrawò","Согласие на голос":"Ìfọwọ́sí ohùn","Настройка озвучки":"Ètò kíkà sókè","Прогресс игр":"Ìlọsíwájú eré","Прогресс историй":"Ìlọsíwájú ìtàn","Прогресс квестов":"Ìlọsíwájú ìpèníjà","Не удалось прочитать: это не файл данных «Рядом».":"Kò lè kà á: èyí kì í ṣe fáìlì dátà Ryadom.","Это не файл данных «Рядом».":"Èyí kì í ṣe fáìlì dátà Ryadom.","В файле нет данных для восстановления.":"Kò sí dátà láti dá padà nínú fáìlì náà.","Пока ничего не сохранено":"Kò sí nǹkan tí a fi pamọ́ síbẹ̀","Данные для переноса":"Dátà fún gbígbé lọ","Выбери, куда сохранить: «Файлы», облако, почта или мессенджер себе.":"Yan ibi tí o fẹ́ fi pamọ́ sí: «Fáìlì», ìkùukùu, ímeèlì tàbí áàpù ìfiránṣẹ́ sí ara rẹ.","Не получилось открыть «Поделиться». Воспользуйся кнопкой «Скопировать текст».":"Kò lè ṣí «Pín». Lo bọ́tìnnì «Da ọ̀rọ̀ kọ».","Файл сохраняется. Если ничего не произошло — воспользуйся кнопкой «Скопировать текст».":"A ń fi fáìlì pamọ́. Bí kò bá sí ohun tó ṣẹlẹ̀, lo bọ́tìnnì «Da ọ̀rọ̀ kọ».","Не получилось сохранить файл. Воспользуйся кнопкой «Скопировать текст».":"Kò lè fi fáìlì pamọ́. Lo bọ́tìnnì «Da ọ̀rọ̀ kọ».","Скопировано. Вставь в заметки или сообщение себе.":"A ti dà á kọ. Lẹ̀ ẹ́ mọ́ àkọsílẹ̀ tàbí ìfiránṣẹ́ sí ara rẹ.","Скопировать автоматически не вышло. Текст выделен — скопируй его вручную.":"Kò lè dà á kọ fúnra rẹ̀. A ti yan ọ̀rọ̀ náà — dà á kọ fúnra rẹ.","Файл слишком большой.":"Fáìlì náà tóbi jù.","Вставь сюда скопированный текст и нажми кнопку ещё раз":"Lẹ ọ̀rọ̀ tí o dà kọ síbí kí o tún tẹ bọ́tìnnì náà","Всё удалено. Обновляю приложение…":"A ti pa gbogbo rẹ̀ rẹ́. A ń tún áàpù bẹ̀rẹ̀…","Где хранятся":"Ibi tí a ń tọ́jú rẹ̀ sí","Что передаётся наружу":"Ohun tí a ń fi ránṣẹ́ síta","Что приложение не делает":"Ohun tí áàpù kò ṣe","Важно":"Ó ṣe pàtàkì","Новых мест для добавления нет. Отметь любимые в разделе «Места» или посещения в дневнике.":"Kò sí ibi tuntun láti fi kún un. Sàmì sí àwọn àyànfẹ́ ní «Àwọn ibi» tàbí ìbẹ̀wò nínú ìwé ìrántí.","Сейчас записи не используются: ни в разговоре, ни в подсказках, ни на сервере.":"A kò lo àwọn àkọsílẹ̀ báyìí: kì í ṣe nínú ìjíròrò, àbá tàbí lórí sáfà.","Романтично":"Ìfẹ́","Весело":"Ìgbádùn","Хочется нового":"Mo fẹ́ nǹkan tuntun","Устало":"Ó rẹ̀ mí","Хочется общения":"Mo fẹ́ alábàákẹ́gbẹ́","Расстояние неизвестно":"A kò mọ ìjìnnà","Сад":"Ọgbà","Библиотека":"Ilé ìkàwé","Музей":"Ilé ìṣẹ̀m̀báyé","Смотровая площадка":"Ibi ìwòran","Ресторан":"Ilé oúnjẹ","Галерея":"Ibi àwòrán","Кинотеатр":"Ilé sinimá","Театр":"Ilé ìṣeré","Достопримечательность":"Ibi ìfanimọ́ra","Арт-пространство":"Ibi iṣẹ́ ọnà","Книжный магазин":"Ilé ìtajà ìwé","Бар":"Ilé ọtí","Уже есть в твоём дневнике":"Ó ti wà nínú ìwé ìrántí rẹ","Отметок об этом месте в дневнике: {0}":"Àmì ibi yìí nínú ìwé ìrántí: {0}","Любимое место · под выбранное настроение может подойти другое":"Ibi àyànfẹ́ · ibòmíì lè bá ìṣesí tí o yàn mu","На карте ↗":"Lórí máàpù ↗","Была/был здесь":"Mo ti wá síbí","01 / ТВОИ МЕСТА":"01 / ÀWỌN IBI RẸ","Любимые сначала":"Àwọn àyànfẹ́ kọ́kọ́","02 / ПОБЛИЗОСТИ":"02 / NÍTÒSÍ","Новые места рядом":"Àwọn ibi tuntun nítòsí","Показано {0} мест рядом с «{1}».":"A ń fi ibi {0} hàn nítòsí «{1}».","Найдено {0} мест в радиусе около 2 км. Данные OpenStreetMap могут быть неполными.":"A rí ibi {0} láàrin bí kìlómítà 2. Dátà OpenStreetMap lè má pé.","Поблизости пока не нашлось мест под это настроение. Попробуй другой район или настроение.":"Kò tíì sí ibi nítòsí fún ìṣesí yìí. Gbìyànjú àgbègbè tàbí ìṣesí mìíràn.","Поиск новых мест сейчас недоступен. Любимые места из дневника остаются здесь. Попробуй позже или укажи другой район.":"Wíwá ibi tuntun kò sí báyìí. Àwọn ibi àyànfẹ́ láti inú ìwé ìrántí ṣì wà níbí. Gbìyànjú lẹ́yìn tàbí yan àgbègbè mìíràn.","Этот браузер не поддерживает определение местоположения. Введи город вручную.":"Aṣàwákiri yìí kò ṣe àtìlẹ́yìn fún ibùdó. Tẹ ìlú wọlé fúnra rẹ.","Запрашиваем местоположение…":"A ń béèrè ibùdó…","текущей точки":"ibi tí o wà","Не удалось получить местоположение. Введи город или район вручную.":"Kò lè rí ibùdó. Tẹ ìlú tàbí àgbègbè wọlé fúnra rẹ.","Не удалось найти этот город или район. Попробуй уточнить название.":"Kò rí ìlú tàbí àgbègbè yìí. Gbìyànjú orúkọ tó péye jù.","Не удалось найти город сейчас. Попробуй ещё раз позже или используй геолокацию.":"Kò lè rí ìlú náà báyìí. Gbìyànjú lẹ́yìn tàbí lo ibùdó.","Убрать из любимых":"Yọ kúrò nínú àyànfẹ́","Изменить место":"Yí ibi padà","Или выбери любимое:":"Tàbí yan àyànfẹ́ kan:","Ты":"Ìwọ","МЕНЮ":"ÀKÓJỌ","Попробовать ещё раз":"Gbìyànjú lẹ́ẹ̀kan sí i","Дальше →":"Ìtẹ̀síwájú →","Скопировать":"Da kọ","Сначала напиши свою версию.":"Kọ́kọ́ kọ ti ara rẹ.","Скопировано.":"A ti dà á kọ.","Скопируй текст вручную.":"Da ọ̀rọ̀ náà kọ fúnra rẹ.","Запомнить в «Обо мне»":"Fi pamọ́ sí «Nípa mi»","Записано в «Обо мне».":"A ti fi pamọ́ sí «Nípa mi».","К играм":"Sí àwọn eré","Озвучка ответов включена":"Kíka ìdáhùn sókè ti tàn","Озвучка включена.":"Kíkà sókè ti tàn.","Данные «Рядом»":"Dátà Ryadom","Копия данных приложения «Рядом». Храни её в надёжном месте.":"Ẹ̀dà dátà áàpù Ryadom. Tọ́jú rẹ̀ sí ibi ààbò.","Сохранить копию":"Fi ẹ̀dà pamọ́","Как ты сегодня? Можно отметить состояние за минуту.":"Báwo ni o ṣe wà lónìí? O lè sàmì ipò rẹ ní ìṣẹ́jú kan.","Минутка для себя: как прошёл день?":"Ìṣẹ́jú kan fún ara rẹ: báwo ni ọjọ́ rẹ ṣe lọ?","Если день был непростым — я рядом. Можно просто отметить настроение.":"Bí ọjọ́ náà bá le — mo wà níbí. O lè kàn sàmì ìṣesí rẹ.","Напоминания недоступны на этом устройстве.":"Ìránnilétí kò sí lórí ẹ̀rọ yìí.","Напоминание выключено.":"A ti pa ìránnilétí.","Уведомления запрещены. Их можно разрешить в настройках телефона для приложения «Рядом».":"A ti dí ìfitónilétí. O lè gbà wọ́n láàyè nínú ètò fóònù rẹ fún áàpù Ryadom.","Напоминание":"Ìránnilétí","Раз в день мягко напомню отметить состояние. Работает без интернета, ничего никуда не отправляется.":"Lẹ́ẹ̀kan lójúmọ́ màá rán ọ létí pẹ̀lẹ́pẹ̀lẹ́ láti sàmì ipò rẹ. Ó ń ṣiṣẹ́ láìsí íńtánẹ́ẹ̀tì, a kò fi nǹkan kan ránṣẹ́.","Ежедневное напоминание":"Ìránnilétí ojoojúmọ́","Каждый день":"Lójoojúmọ́","Время напоминания":"Àkókò ìránnilétí","Похоже, сейчас тревожно.":"Ó dàbí pé àníyàn ń bá ọ báyìí.","Похоже, сейчас грустно.":"Ó dàbí pé inú rẹ bàjẹ́ báyìí.","Похоже, сейчас много злости.":"Ó dàbí pé ìbínú pọ̀ báyìí.","Похоже, сил сейчас совсем немного.":"Ó dàbí pé agbára rẹ kéré gan-an báyìí.","Похоже, сейчас одиноко.":"Ó dàbí pé ìdáwà ń bá ọ báyìí.","Похоже, это задело.":"Ó dàbí pé èyí dùn ọ́.","Похоже, рядом с этим есть чувство вины или стыда.":"Ó dàbí pé ẹ̀bi tàbí ìtìjú wà pẹ̀lú èyí.","Как хорошо это слышать!":"Ó dára gan-an láti gbọ́ èyí!","Слышу, что это связано с работой.":"Mo gbọ́ pé ó jẹ mọ́ iṣẹ́.","Слышу, что это связано с семьёй.":"Mo gbọ́ pé ó jẹ mọ́ ẹbí.","Слышу, что это связано с отношениями.":"Mo gbọ́ pé ó jẹ mọ́ ìbáṣepọ̀.","Слышу, что это связано с друзьями.":"Mo gbọ́ pé ó jẹ mọ́ àwọn ọ̀rẹ́.","Слышу, что это связано со здоровьем.":"Mo gbọ́ pé ó jẹ mọ́ ìlera.","Слышу, что это связано с деньгами.":"Mo gbọ́ pé ó jẹ mọ́ owó.","Слышу, что это связано с учёбой.":"Mo gbọ́ pé ó jẹ mọ́ ẹ̀kọ́.","Я слушаю. Что было дальше?":"Mo ń gbọ́. Kí ló ṣẹlẹ̀ lẹ́yìn náà?","Это звучит непросто. Что сейчас ощущается сильнее всего?":"Èyí dàbí ẹni pé ó le. Kí lo ń ní ìmọ̀lára rẹ̀ jù báyìí?","Понимаю. Что для тебя здесь самое важное?":"Ó yé mi. Kí ló ṣe pàtàkì jù fún ọ níbí?","Спасибо, что рассказываешь. Как это на тебя повлияло?":"O ṣé tí o sọ fún mi. Báwo ni èyí ṣe nípa lórí rẹ?","Если посмотреть на это со стороны — что хотелось бы изменить в первую очередь?":"Bí o bá wò ó láti ìta — kí lo fẹ́ yí padà kọ́kọ́?","Что помогло бы тебе хоть немного прямо сейчас?":"Kí ló lè ràn ọ́ lọ́wọ́ díẹ̀ báyìí?","Злюсь":"Mo bínú","Одиноко":"Ìdáwà","Всё хорошо":"Gbogbo nǹkan dára","Куда сегодня сходить?":"Ibo ni kí n lọ lónìí?","Просто выговориться":"Kàn sọ̀rọ̀ jáde","Небольшой шаг, чтобы стало легче":"Ìgbésẹ̀ kékeré láti fúyẹ́","Потренировать трудный разговор":"Ṣe ìdánrawò ìjíròrò tó le","Куда сходить или что поесть":"Ibo ni kí n lọ tàbí kí ni kí n jẹ","Привет. Я — «Рядом». Можно написать, как ты, своими словами или выбрать подсказку.":"Ẹ n lẹ. Èmi ni Ryadom. O lè kọ bí o ṣe wà ní ọ̀rọ̀ ara rẹ tàbí yan àbá kan.","На этом языке я понимаю простые фразы. Подсказки-кнопки помогут быть точнее.":"Ní èdè yìí, mo ń lóye gbólóhùn tó rọrùn. Bọ́tìnnì àbá yóò ràn wá lọ́wọ́ láti péye sí i.","Как хорошо это слышать! Что сегодня порадовало?":"Ó dára gan-an láti gbọ́! Kí ló mú inú rẹ dùn lónìí?","Куда сходить отметить?":"Ibo ni kí n lọ ṣe àjọyọ̀?","Записать в дневник":"Kọ ọ́ sínú ìwé ìrántí","Есть и сложная часть":"Apá tó le náà wà","Что сейчас было бы полезнее?":"Kí ni yóò wúlò jù báyìí?","Вот что можно попробовать. Любой шаг можно остановить.":"Èyí ni ohun tí o lè gbìyànjú. O lè dá ìgbésẹ̀ èyíkéyìí dúró.","Лучше просто поговорим":"Ẹ jẹ́ ká kàn sọ̀rọ̀","Подобрать небольшой шаг":"Wá ìgbésẹ̀ kékeré kan","Продолжу рассказывать":"Màá máa sọ ọ́ lọ","Спасибо за разговор. Я здесь, когда захочется вернуться.":"O ṣé fún ìjíròrò náà. Mo wà níbí nígbàkígbà tí o bá fẹ́ padà wá.","Начать новый разговор":"Bẹ̀rẹ̀ ìjíròrò tuntun","Открыть дневник":"Ṣí ìwé ìrántí","Похоже, сейчас очень много злости. Если есть риск навредить другому человеку — остановись и выйди из ситуации: на воздух, в другую комнату. Если опасность рядом — звони в экстренную службу.":"Ó dàbí pé ìbínú pọ̀ gan-an báyìí. Bí ewu bá wà pé o lè pa ẹlòmíì lára, dúró kí o kúrò níbẹ̀: jáde síta tàbí lọ sí yàrá mìíràn. Bí ewu bá wà nítòsí, pe iṣẹ́ pàjáwìrì.","То, что ты описываешь, звучит небезопасно. Твоя безопасность важнее всего. Если опасность рядом прямо сейчас — постарайся уйти в безопасное место и позвони в экстренную службу.":"Ohun tí o ń ṣàpèjúwe kò dàbí ẹni pé ó ní ààbò. Ààbò rẹ ló ṣe pàtàkì jù. Bí ewu bá wà nítòsí báyìí, gbìyànjú láti lọ sí ibi ààbò kí o sì pe iṣẹ́ pàjáwìrì.","Спасибо, что ты об этом говоришь. Твоя безопасность сейчас важнее всего. С этим не нужно справляться без поддержки: позвони на линию помощи или человеку, которому доверяешь.":"O ṣé tí o sọ èyí. Ààbò rẹ ló ṣe pàtàkì jù báyìí. O kò ní láti dojú kọ èyí láìsí àtìlẹ́yìn: pe ìlà ìrànlọ́wọ́ tàbí ẹni tí o gbẹ́kẹ̀lé.","Показать текст для близкого":"Fi ọ̀rọ̀ hàn fún ẹni tó sún mọ́ ọ","Сейчас я в безопасности":"Mo wà ní ààbò báyìí","Если опасность прямо сейчас — экстренная служба: 112 (в большинстве стран).":"Bí ewu bá wà báyìí — iṣẹ́ pàjáwìrì: 112 (ní ọ̀pọ̀ orílẹ̀-èdè).","Линии помощи в других странах: findahelpline.com":"Ìlà ìrànlọ́wọ́ ní àwọn orílẹ̀-èdè mìíràn: findahelpline.com","Пожалуйста. Я рядом.":"Kò tópẹ́. Mo wà níbí.","Нет, я не врач и не психолог: не ставлю диагнозов и не лечу. Я помогаю выговориться, назвать, что происходит, и сделать небольшой шаг. Если тяжёлое состояние держится долго или мешает жить, стоит обратиться к специалисту.":"Rárá, èmi kì í ṣe dókítà tàbí onímọ̀ ọpọlọ: n kò ń ṣàyẹ̀wò àrùn tàbí tọ́jú. Mo ń ràn ọ́ lọ́wọ́ láti sọ̀rọ̀ jáde, dárúkọ ohun tó ń ṣẹlẹ̀, kí o sì gbé ìgbésẹ̀ kékeré. Bí ipò tó wúwo bá pẹ́ tàbí ń dí ìgbésí ayé rẹ lọ́wọ́, ó dára láti rí amọ̀ṣẹ́.","Я «Рядом» — программа, а не человек. Я не врач и не заменяю специалиста.":"Èmi ni Ryadom — ètò kọ̀ǹpútà ni mí, kì í ṣe ènìyàn. Èmi kì í ṣe dókítà, n kò sì rọ́pò amọ̀ṣẹ́.","Хорошо, не будем. Ничего объяснять не нужно. Можно просто побыть рядом или выбрать другое.":"Ó dára, a kò ní ṣe é. O kò nílò láti ṣàlàyé nǹkan kan. A lè kàn wà pa pọ̀ tàbí yan nǹkan mìíràn.","Я рядом. Начнём с самого простого: что сейчас ближе?":"Mo wà níbí. Ẹ jẹ́ ká bẹ̀rẹ̀ pẹ̀lú èyí tó rọrùn jù: kí ló sún mọ́ bí o ṣe ń rí báyìí jù?","Привет. Что сейчас происходит? Можно написать своими словами или выбрать подсказку.":"Ẹ n lẹ. Kí ló ń ṣẹlẹ̀ báyìí? O lè kọ ní ọ̀rọ̀ ara rẹ tàbí yan àbá kan.","Это стоит запомнить. Хочешь отметить это — сходить куда-нибудь или записать в дневник?":"Èyí yẹ ní rírántí. Ṣé o fẹ́ ṣe àjọyọ̀ rẹ̀ — lọ sí ibì kan tàbí kọ ọ́ sínú ìwé ìrántí?","А что здесь сильнее всего?":"Kí ló lágbára jù níbí?","Обида":"Ìbànújẹ́","Усталость":"Àárẹ̀","Хочу понять точнее. Что ближе всего к тому, что сейчас внутри? Можно выбрать подсказку.":"Mo fẹ́ lóye dáadáa. Kí ló sún mọ́ ohun tó wà nínú rẹ báyìí jù? O lè yan àbá kan.","Из того, что известно о тебе:":"Láti inú ohun tí mo mọ̀ nípa rẹ:","В разделе «Места» можно выбрать настроение и посмотреть, что рядом.":"Ní «Àwọn ibi», o lè yan ìṣesí kí o sì wo ohun tó wà nítòsí.","Открыть «Места»":"Ṣí «Àwọn ibi»","Расскажу, что на душе":"Màá sọ ohun tó wà lọ́kàn mi","Расскажи, что ещё происходит.":"Sọ fún mi ohun mìíràn tó ń ṣẹlẹ̀.","Я слушаю. Можно писать как получается — кусками, без порядка.":"Mo ń gbọ́. O lè kọ bí ó bá ṣe wá — ní ẹ̀yà-ẹ̀yà, láìsí ètò.","Тренажёры трудных разговоров пока доступны только на русском языке. Можно открыть их или выбрать другое.":"Ìdánrawò ìjíròrò tó le wà ní èdè Rọ́ṣíà nìkan fún báyìí. O lè ṣí wọn tàbí yan nǹkan mìíràn.","Открыть тренажёры":"Ṣí ìdánrawò","Я слушаю.":"Mo ń gbọ́.","Хорошо. Если станет хуже — линии помощи выше, и можно вернуться сюда в любой момент.":"Ó dára. Bí ó bá burú sí i — ìlà ìrànlọ́wọ́ wà lókè, o sì lè padà síbí nígbàkígbà.","Можно отправить близкому:":"O lè fi ránṣẹ́ sí ẹni tó sún mọ́ ọ:","Мне сейчас очень тяжело. Пожалуйста, побудь со мной или позвони мне сейчас. Помоги обратиться за помощью.":"Ó le fún mi gan-an báyìí. Jọ̀ọ́ dúró pẹ̀lú mi tàbí pè mí báyìí. Ràn mí lọ́wọ́ láti wá ìrànlọ́wọ́.","Хорошо, что стало хоть немного легче. Хочешь остановиться на этом или продолжить?":"Ó dára pé ó fúyẹ́ díẹ̀. Ṣé o fẹ́ dúró síbí tàbí tẹ̀síwájú?","Жаль, что стало тяжелее. Давай не продолжать эту практику. Можно связаться с близким человеком или выбрать другой, более мягкий шаг.":"Ó dùn mí pé ó le sí i. Ẹ má jẹ́ ká tẹ̀síwájú ìdánrawò yìí. O lè kàn sí ẹni tó sún mọ́ ọ tàbí yan ìgbésẹ̀ mìíràn tó rọ̀ jù.","Иногда эффект приходит не сразу. Можно попробовать другой способ или просто поговорить.":"Nígbà mìíràn ipa rẹ̀ kì í dé lẹ́sẹ̀kẹsẹ̀. O lè gbìyànjú ọ̀nà mìíràn tàbí kàn sọ̀rọ̀.","Другой способ":"Ọ̀nà mìíràn","Подобрано {x}. Можно выбрать любое или ничего.":"A ti yàn: {x}. O lè yan èyíkéyìí tàbí kò sí.","по последней отметке «{q}»":"gẹ́gẹ́ bí àmì rẹ tó gbẹ̀yìn «{q}»","по последней отметке «{q}» и позднему времени":"gẹ́gẹ́ bí àmì rẹ tó gbẹ̀yìn «{q}» àti àkókò alẹ́","{x} · Открыть →":"{x} · Ṣí i →","{0} из {1}":"{0} nínú {1}","Отметить шаг цепочки: {x}":"Sàmì ìgbésẹ̀ ẹ̀wọ̀n: {x}","Открыть практику: {x}":"Ṣí ìdánrawò: {x}","Открыть тренажёр: {x}":"Ṣí ìdánrawò ìjíròrò: {x}","Убрать «{q}»":"Yọ «{q}» kúrò","Удалить: {x}":"Pa rẹ́: {x}","Идея на сегодня: {x}.":"Èrò fún òní: {x}.","Идея на сегодня: {x}. Лучше без: {y}.":"Èrò fún òní: {x}. Ó sàn láìsí: {y}.","поесть":"jẹun","побыть":"lo àkókò","{0} Б":"{0} B","{0} КБ":"{0} KB","Данные восстановлены ({0}). Обновляю приложение…":"A ti dá dátà padà ({0}). A ń tún áàpù bẹ̀rẹ̀…","Добавлено записей: {0}":"Àkọsílẹ̀ tí a fi kún: {0}","тебе обычно подходит — {x}. Выбирай места с учётом этого.":"ohun tó sábà máa ń bá ọ mu — {x}. Yan àwọn ibi pẹ̀lú èyí lọ́kàn.","тебе обычно подходит — {x}. Лучше без: {y}. Выбирай места с учётом этого.":"ohun tó sábà máa ń bá ọ mu — {x}. Ó sàn láìsí: {y}. Yan àwọn ibi pẹ̀lú èyí lọ́kàn.","{0} м":"mítà {0}","{0} км":"kìlómítà {0}","Убрать из любимых: {x}":"Yọ kúrò nínú àyànfẹ́: {x}","В любимые: {x}":"Fi kún àyànfẹ́: {x}","«{q}» добавлено в дневник за сегодня.":"A ti fi «{q}» kún ìwé ìrántí òní.","Ищем места рядом с «{q}»…":"A ń wá àwọn ibi nítòsí «{q}»…","Ищем «{q}»…":"A ń wá «{q}»…","Сохранён город «{q}». Выбирай настроение — подборка обновится.":"A ti fi ìlú «{q}» pamọ́. Yan ìṣesí — àṣàyàn yóò ṣe àtúnṣe.","Найдено практик: {0} из {1}":"Ìdánrawò tí a rí: {0} nínú {1}","Показать ещё ({0})":"Fi púpọ̀ hàn ({0})","В диалоге: {x}":"Nínú ìjíròrò: {x}","Удалить тексты разговоров за {x}? Отметки состояния останутся.":"Pa ọ̀rọ̀ ìjíròrò {x} rẹ́? Àmì ipò yóò wà.","Практики: {x}":"Ìdánrawò: {x}","Шаг {0} из {1}":"Ìgbésẹ̀ {0} nínú {1}","Подсказка: {x}":"Àbá: {x}","Источник: {x}":"Orísun: {x}","Пройдено стилей: {0} из {1}":"Àwọn ọ̀nà tí a parí: {0} nínú {1}","День {0}":"Ọjọ́ {0}","{x} по дням":"{x} ní ọjọọjọ́","Готово: каждый день в {0}:{1}. Пропускать можно — это просто приглашение.":"Ó ti parí: lójoojúmọ́ ní {0}:{1}. Fífò ó dára — ìpè lásán ni.","Чаще всего тебе помогала практика «{q}» ({0} раз). Это личная заметка, не медицинский вывод.":"Ìdánrawò tó ràn ọ́ lọ́wọ́ jù ni «{q}» (ìgbà {0}). Àkọsílẹ̀ ara ẹni ni èyí, kì í ṣe ìpinnu ìṣègùn.","Удалить «{q}» из этого дня?":"Yọ «{q}» kúrò ní ọjọ́ yìí?","{0} место":"ibi {0}","{0} места":"ibi {0}","{0} мест":"ibi {0}","Играть: {x}":"Ṣeré: {x}","{0} мин":"ìṣẹ́jú {0}","{0} минуты":"ìṣẹ́jú {0}","{0} минут":"ìṣẹ́jú {0}","{0} минута":"ìṣẹ́jú {0}","{0}–{1} минут":"ìṣẹ́jú {0}–{1}","рядом":"ryadom","Я":"Èmi","на каждый день":"fún ojoojúmọ́","← К играм":"← Sí àwọn eré",". Оценки и популярность в соцсетях появятся только после подключения проверенного источника данных.":". Ìdíyelé àti òkìkí lórí ìkànnì àjọlò yóò hàn lẹ́yìn tí a bá so orísun dátà tí a fọwọ́ sí nìkan.","есть разговор":"ìjíròrò wà","есть отметка состояния":"àmì ipò wà","есть посещённые места":"àwọn ibi tí a lọ wà","Квесты и сюжетные игры пока доступны только на русском языке. Перевод появится в следующих версиях.":"Àwọn ìpèníjà àti eré ìtàn wà ní èdè Rọ́ṣíà nìkan fún báyìí. Ìtumọ̀ yóò dé ní àwọn ẹ̀yà tó ń bọ̀.","Не знаю, как сказать":"N kò mọ bí màá ṣe sọ ọ́","Если сейчас очень тяжело":"Bí nǹkan bá le gan-an báyìí","С этим не нужно справляться в одиночку. Выбери то, что получится сейчас.":"O kò ní láti dojú kọ èyí nìkan. Yan ohun tí o lè ṣe báyìí.","Позвонить":"Pè","Написать близкому":"Kọ̀wé sí ẹni tó sún mọ́ ọ","Мне сейчас очень тяжело. Пожалуйста, позвони мне или побудь рядом. Помоги мне получить помощь.":"Ó le fún mi gan-an báyìí. Jọ̀ọ́ pè mí tàbí dúró pẹ̀lú mi. Ràn mí lọ́wọ́ láti rí ìrànlọ́wọ́.","Пережить ближайшие минуты":"Kọjá ìṣẹ́jú díẹ̀ tó ń bọ̀","Медленный выдох длиннее вдоха. Назови пять вещей, которые видишь вокруг. Если рядом есть что-то опасное — отложи это подальше или выйди в другое место.":"Mí síta díẹ̀díẹ̀, pẹ́ ju mímí sínú lọ. Dárúkọ nǹkan márùn-ún tí o rí ní àyíká rẹ. Bí nǹkan eléwu bá wà nítòsí, gbé e jìnnà tàbí lọ sí ibòmíì.","Дыхание вместе со мной":"Mí pẹ̀lú mi","Мой план безопасности":"Ètò ààbò mi","Заполни, когда немного спокойнее. План останется только на этом устройстве и откроется здесь в трудную минуту.":"Kọ ọ́ nígbà tí ara bá balẹ̀ díẹ̀. Ètò náà yóò wà lórí ẹ̀rọ yìí nìkan, yóò sì ṣí síbí ní àkókò ìṣòro.","Как я понимаю, что мне становится хуже":"Bí mo ṣe ń mọ̀ pé ipò mi ń burú sí i","Что помогает мне хоть немного":"Ohun tó ń ràn mí lọ́wọ́ díẹ̀","Кому могу написать или позвонить":"Ẹni tí mo lè kọ̀wé sí tàbí pè","Как сделать обстановку вокруг безопаснее":"Bí mo ṣe lè mú àyíká mi ní ààbò sí i","«Рядом» — не экстренная служба и может не распознать, что тебе плохо. Если есть риск для жизни, звони 112 или обратись к человеку рядом.":"Ryadom kì í ṣe iṣẹ́ pàjáwìrì, ó sì lè má mọ̀ pé ara rẹ kò yá. Bí ewu bá wà fún ẹ̀mí, pe 112 tàbí kàn sí ẹnì kan nítòsí.","Мне очень плохо":"Ara mi kò yá rárá","Мне сейчас очень плохо — открыть помощь":"Ara mi kò yá rárá báyìí — ṣí ìrànlọ́wọ́","Открыть экран помощи":"Ṣí ojú-ìwé ìrànlọ́wọ́","Прежде чем продолжить, хочу спросить прямо, потому что это важно: ты сейчас думаешь о том, чтобы причинить себе вред или не жить?":"Kí a tó tẹ̀síwájú, mo fẹ́ béèrè tààrà nítorí ó ṣe pàtàkì: ṣé o ń ronú báyìí láti pa ara rẹ lára tàbí láti má wà láàyè?","Да":"Bẹ́ẹ̀ni","Не знаю":"N kò mọ̀","Нет, это другое":"Rárá, nǹkan mìíràn ni","Спасибо за ответ. Продолжим.":"O ṣé fún ìdáhùn rẹ. Ẹ jẹ́ ká tẹ̀síwájú.","Письмо себе из детства":"Lẹ́tà sí ara rẹ ní ìgbà èwe","Вернуться к ситуации из детства, которая до сих пор отзывается: назвать чувства, признать, что это было, и отпустить.":"Padà sí ìṣẹ̀lẹ̀ ìgbà èwe tó ṣì ń dún nínú rẹ: dárúkọ ìmọ̀lára, gbà pé ó ṣẹlẹ̀, kí o sì jẹ́ kó lọ.","Бережная практика о детском опыте. Без подробностей — только то, что чувствуется сейчас.":"Ìdánrawò onírẹ̀lẹ̀ nípa ìrírí ìgbà èwe. Kò sí àlàyé kíkún — ohun tí o ń rí lára báyìí nìkan.","Детский опыт":"Ìgbà èwe","страх":"ẹ̀rù","стыд":"ìtìjú","одиночество":"ìdáwà","обида":"ìbànújẹ́ ọkàn","злость":"ìbínú","беспомощность":"àìlólùrànlọ́wọ́","вина":"ẹ̀bi","растерянность":"ìdàrúdàpọ̀","горло":"ọ̀fun","грудь":"àyà","живот":"ikùn","плечи и шея":"èjìká àti ọrùn","руки":"ọwọ́","не чувствую в теле":"n kò rí i lára mi","защиты":"ààbò","утешения":"ìtùnú","чтобы выслушали":"kí wọ́n gbọ́ mi","чтобы объяснили, что происходит":"kí wọ́n ṣàlàyé ohun tó ń ṣẹlẹ̀","чтобы не винили":"kí wọ́n má dá mi lẹ́bi","чтобы взрослый был рядом":"àgbàlagbà kan lẹ́gbẹ̀ẹ́ mi","чтобы заметили и похвалили":"kí wọ́n kíyèsí mi kí wọ́n sì yìn mí","права на свои чувства":"ẹ̀tọ́ sí ìmọ̀lára mi","Это не твоя вина.":"Kì í ṣe ẹ̀bi rẹ.","Ты имеешь право чувствовать то, что чувствуешь.":"O ní ẹ̀tọ́ láti ní ìmọ̀lára tí o ní.","Тебе досталось слишком много для такого возраста.":"O gbé ẹrù tó pọ̀ jù fún ọjọ́ orí yẹn.","Я вижу, как тебе было трудно.":"Mo rí bí ó ti le tó fún ọ.","Теперь я рядом и могу о тебе позаботиться.":"Báyìí mo wà níbí, mo sì lè tọ́jú rẹ.","В твоём возрасте никто не справился бы лучше.":"Kò sí ẹni ọjọ́ orí rẹ tó lè ṣe é dáadáa jù.","Это было.":"Ó ṣẹlẹ̀.","Это было больно.":"Ó dùn.","В том возрасте нельзя было сделать больше.":"Ní ọjọ́ orí yẹn, kò ṣeé ṣe láti ṣe ju bẹ́ẹ̀ lọ.","Это закончилось. Сейчас я взрослый человек и я в безопасности.":"Ó ti parí. Báyìí mo ti dàgbà, mo sì wà ní ààbò.","Принять — не значит согласиться, что так было правильно.":"Gbígbà kò túmọ̀ sí pé ó tọ̀nà.","Практика «Письмо себе из детства»":"Ìdánrawò «Lẹ́tà sí ara rẹ ní ìgbà èwe»","◐ РЯДОМ · ПРАКТИКА":"◐ RYADOM · ÌDÁNRAWÒ","Перед началом":"Kí o tó bẹ̀rẹ̀","← Назад":"← Padà","Мне становится слишком тяжело":"Ó ń le jù fún mi","ОСТАНОВКА — ЭТО ТОЖЕ ЗАБОТА":"DÍDÚRÓ NÁÀ JẸ́ ÌTỌ́JÚ","Остановиться — правильное решение":"Dídúró ni ìpinnu tó tọ̀nà","Заметить свой предел — важный навык, а не неудача. Вернись в «сейчас»: посмотри вокруг, назови пять предметов, медленно выдохни. Воспоминание никуда не денется — к нему можно вернуться позже, лучше вместе со специалистом.":"Kíkíyèsí ààlà rẹ jẹ́ ọgbọ́n pàtàkì, kì í ṣe ìkùnà. Padà sí «báyìí»: wo àyíká rẹ, dárúkọ nǹkan márùn-ún, mí síta díẹ̀díẹ̀. Ìrántí náà kò ní lọ — o lè padà sí i nígbà míì, ó dára jù pẹ̀lú amọ̀ṣẹ́.","Если состояние не отпускает или появляются мысли навредить себе — открой экран помощи: там номера, текст для близкого и план безопасности.":"Bí ipò náà kò bá dẹ̀ tàbí èrò láti pa ara rẹ lára bá wá — ṣí ojú-ìwé ìrànlọ́wọ́: nọ́mbà, ọ̀rọ̀ fún ẹni tó sún mọ́ ọ àti ètò ààbò wà níbẹ̀.","ПРАКТИКА ЗАВЕРШЕНА":"ÌDÁNRAWÒ TI PARÍ","Встреча с собой из прошлого состоялась":"Ìpàdé pẹ̀lú ara rẹ ti àtijọ́ ti ṣẹlẹ̀","Чувства могут отзываться ещё какое-то время — это нормально. Сегодня стоит сделать что-то тёплое и простое для себя: поесть, выйти на воздух, написать близкому человеку.":"Ìmọ̀lára lè máa dún fún ìgbà díẹ̀ — ìyẹn wọ́pọ̀. Lónìí, ṣe ohun tó gbóná, tó rọrùn fún ara rẹ: jẹun, jáde síta, kọ̀wé sí ẹni tó sún mọ́ ọ.","Оценка не отмечена — это нормально.":"A kò dìíyelé — kò burú.","Напряжение стало немного меньше.":"Ìdààmú ti dín kù díẹ̀.","Напряжение выросло. Позаботься о себе сегодня бережнее и, если это не проходит, обратись к специалисту или близкому.":"Ìdààmú ti pọ̀ sí i. Tọ́jú ara rẹ pẹ̀lú ìrẹ̀lẹ̀ jù lónìí, bí kò bá sì lọ, kàn sí amọ̀ṣẹ́ tàbí ẹni tó sún mọ́ ọ.","Напряжение не изменилось. Иногда эффект приходит позже — или нужен другой путь.":"Ìdààmú kò yí padà. Nígbà míì ipa rẹ̀ máa ń dé lẹ́yìn — tàbí ọ̀nà mìíràn ni a nílò.","Если это воспоминание часто возвращается, мешает спать, жить, строить отношения — это повод обратиться к психологу или психотерапевту, который работает с травмой. С ним можно пройти этот путь глубже и безопаснее.":"Bí ìrántí yìí bá ń padà wá léraléra, tí ó ń dí oorun, ìgbésí ayé tàbí ìbáṣepọ̀ — ìdí nìyí láti rí onímọ̀ ọpọlọ tàbí oníwòsàn tó ń ṣiṣẹ́ pẹ̀lú ìpalára ọkàn. Pẹ̀lú rẹ̀, o lè rìn ọ̀nà yìí jinlẹ̀ àti ní ààbò jù.","В дневник сохранены только факт практики и изменение напряжения. Написанное тобой не сохранялось и исчезнет после закрытия.":"Ohun tí a fi pamọ́ sínú ìwé ìrántí ni pé ìdánrawò wáyé àti ìyípadà ìdààmú nìkan. A kò fi ohun tí o kọ pamọ́, yóò sì pòórá nígbà tí o bá pa á.","Бережно, в своём темпе":"Pẹ̀lẹ́pẹ̀lẹ́, ní ìyára ara rẹ","Мы вернёмся к ситуации из детства, которая до сих пор отзывается. Подробности вспоминать не нужно — важно то, что ты чувствуешь сейчас. Остановиться можно в любой момент.":"A ó padà sí ìṣẹ̀lẹ̀ ìgbà èwe tó ṣì ń dún nínú rẹ. O kò nílò láti rántí àlàyé — ohun tí o ń rí lára báyìí ló ṣe pàtàkì. O lè dúró nígbàkígbà.","С каким воспоминанием хочется побыть?":"Ìrántí wo ni o fẹ́ wà pẹ̀lú?","Задевает, но с ним можно побыть 10 минут":"Ó ń kàn mí, ṣùgbọ́n mo lè wà pẹ̀lú rẹ̀ fún ìṣẹ́jú 10","Очень тяжёлое: насилие, сильный страх, то, что накрывает":"Ó wúwo gan-an: ìwà ipá, ẹ̀rù ńlá, ohun tó máa ń bò mí mọ́lẹ̀","С очень тяжёлыми воспоминаниями самостоятельно лучше не работать: они могут накрыть сильнее, чем кажется. Эта практика подходит для чего-то полегче. С тяжёлым опытом бережнее и безопаснее идти к специалисту по травме. Можно выбрать другое, менее тяжёлое воспоминание — или просто закрыть практику.":"Ó sàn láti má dá ṣiṣẹ́ pẹ̀lú ìrántí tó wúwo gan-an: wọ́n lè bò ọ́ mọ́lẹ̀ ju bí ó ṣe dàbí lọ. Ìdánrawò yìí wà fún ohun tó fúyẹ́ jù. Pẹ̀lú ìrírí tó wúwo, ó rọ̀ jù, ó sì ní ààbò jù láti lọ sọ́dọ̀ amọ̀ṣẹ́ ìpalára ọkàn. O lè yan ìrántí mìíràn tó fúyẹ́ jù — tàbí kí o kàn pa ìdánrawò náà.","Насколько тебе неспокойно прямо сейчас?":"Báwo ni ọkàn rẹ ṣe dàrú tó báyìí?","0 — спокойно":"0 — ìbàlẹ̀","10 — очень тяжело":"10 — ó le gan-an","Сейчас напряжение очень высокое. Лучше сначала успокоиться: дыхание, прогулка, разговор с близким. К практике можно вернуться в другой день.":"Ìdààmú ga gan-an báyìí. Ó sàn kí o kọ́kọ́ balẹ̀: mímí, ìrìn, ọ̀rọ̀ pẹ̀lú ẹni tó sún mọ́ ọ. O lè padà sí ìdánrawò ní ọjọ́ míì.","Если ты сейчас в опасности или ситуация из прошлого продолжается — сначала позаботься о безопасности: кнопка «Мне очень плохо» вверху экрана.":"Bí o bá wà nínú ewu báyìí tàbí ìṣẹ̀lẹ̀ àtijọ́ ṣì ń bá a lọ — kọ́kọ́ tọ́jú ààbò rẹ: bọ́tìnnì «Ara mi kò yá rárá» lókè ojú-ìwé.","01 · ОПОРА":"01 · ÌTÌLẸ́YÌN","Сначала — здесь и сейчас":"Àkọ́kọ́ — níbí àti báyìí","Прежде чем идти в прошлое, найдём опору в настоящем. Посмотри вокруг и назови про себя три предмета. Почувствуй, как ты сидишь, как стопы касаются пола.":"Kí a tó lọ sí àtijọ́, ẹ jẹ́ ká rí ìtìlẹ́yìn nínú ìsinsìnyí. Wo àyíká rẹ kí o dárúkọ nǹkan mẹ́ta nínú ọkàn rẹ. Rí bí o ṣe jókòó, bí ẹsẹ̀ rẹ ṣe kan ilẹ̀.","вдох 4 · выдох 6":"mí sínú 4 · mí síta 6","Сделай три медленных выдоха — длиннее вдоха. Вспомни место, человека или вещь, рядом с которыми тебе спокойно. Это твоя опора: к ней можно вернуться в любой момент практики.":"Mí síta díẹ̀díẹ̀ lẹ́ẹ̀mẹ́ta — pẹ́ ju mímí sínú lọ. Rántí ibì kan, ẹnì kan tàbí nǹkan kan tí ara rẹ máa ń balẹ̀ lẹ́gbẹ̀ẹ́ rẹ̀. Ìtìlẹ́yìn rẹ nìyẹn: o lè padà sí i nígbàkígbà nínú ìdánrawò.","Опора есть →":"Mo ní ìtìlẹ́yìn →","02 · ТА СИТУАЦИЯ":"02 · ÌṢẸ̀LẸ̀ YẸN","Одной строкой, без подробностей":"Ní ìlà kan, láìsí àlàyé","Сколько тебе было лет и что происходило — коротко, как заголовок. Не нужно пересказывать и прокручивать сцену. Можно ничего не писать, а просто держать её в уме.":"Ọmọ ọdún mélòó ni ọ́, kí ló sì ń ṣẹlẹ̀ — ní ṣókí, bí àkọlé. O kò nílò láti tún ìtàn náà sọ tàbí tún un wò. O lè má kọ nǹkan kan, kí o kàn fi sí ọkàn.","Мне было примерно… (необязательно)":"Mo jẹ́ bí… (kò pọndandan)","Например: «Мне 8, родители ругаются, а я сижу в своей комнате»":"Fún àpẹẹrẹ: «Ọmọ ọdún 8 ni mí, àwọn òbí mi ń jà, mo sì jókòó nínú yàrá mi»","Текст остаётся только на этом экране и не сохраняется.":"Ọ̀rọ̀ náà wà lórí ojú-ìwé yìí nìkan, a kò sì fi pamọ́.","03 · ЧУВСТВА":"03 · ÌMỌ̀LÁRA","Какие чувства были тогда?":"Kí ni o rí lára nígbà yẹn?","Отметь всё, что откликается. Чувства не бывают «неправильными» — тогда у них были причины.":"Sàmì sí gbogbo ohun tó ń kàn ọ́. Ìmọ̀lára kì í ṣe «àṣìṣe» — wọ́n ní ìdí wọn nígbà yẹn.","Где это отзывается в теле сейчас?":"Níbo ni o ti ń rí i lára rẹ báyìí?","Тогда ребёнок чувствовал: {x}. Эти чувства были естественной реакцией на то, что происходило.":"Nígbà yẹn ọmọ náà ní ìmọ̀lára: {x}. Ìmọ̀lára wọ̀nyí jẹ́ ìdáhùn àdáyébá sí ohun tó ń ṣẹlẹ̀.","Насколько тяжело сейчас?":"Báwo ló ṣe le tó báyìí?","Напряжение сильно выросло. Сейчас лучше остановиться и вернуться к опоре. Это правильное решение, а не слабость.":"Ìdààmú ti pọ̀ sí i gan-an. Ó sàn kí o dúró báyìí kí o padà sí ìtìlẹ́yìn rẹ. Ìpinnu tó tọ̀nà ni, kì í ṣe àìlera.","Остановиться и вернуться к опоре":"Dúró kí o padà sí ìtìlẹ́yìn","04 · ЧЕГО НЕ ХВАТАЛО":"04 · OHUN TÓ ṢALÁÌSÍ","Что тогда было нужно?":"Kí ni o nílò nígbà yẹn?","Каждому ребёнку нужны безопасность, утешение и взрослый рядом. Что было нужно тебе в той ситуации?":"Gbogbo ọmọ nílò ààbò, ìtùnú àti àgbàlagbà lẹ́gbẹ̀ẹ́. Kí ni o nílò nínú ìṣẹ̀lẹ̀ yẹn?","Тебе тогда были нужны: {x}. Это нормальные потребности. То, что их не было, — не твоя вина: заботиться о ребёнке должны взрослые.":"Nígbà yẹn o nílò: {x}. Àwọn àìní wọ̀nyí wọ́pọ̀. Kí wọ́n má sí kì í ṣe ẹ̀bi rẹ: àgbàlagbà ló yẹ kó tọ́jú ọmọdé.","05 · ПРИЗНАТЬ":"05 · GBÀ","Это было":"Ó ṣẹlẹ̀","Принятие — не значит согласиться, что так было правильно, и не значит простить. Это значит перестать спорить с тем, что уже случилось, и забрать силы обратно в настоящее. Прочитай медленно, можно вслух:":"Gbígbà kò túmọ̀ sí pé ó tọ̀nà, kò sì túmọ̀ sí ìdáríjì. Ó túmọ̀ sí dídá ìjà dúró pẹ̀lú ohun tó ti ṣẹlẹ̀, kí o sì mú agbára rẹ padà sí ìsinsìnyí. Kà á díẹ̀díẹ̀, sókè bí o bá fẹ́:","Какая фраза отозвалась сильнее? Побудь с ней пару вдохов.":"Gbólóhùn wo ló kàn ọ́ jù? Wà pẹ̀lú rẹ̀ fún mímí díẹ̀.","06 · СЛОВА СЕБЕ ТОГДА":"06 · Ọ̀RỌ̀ SÍ ARA RẸ TI ÌGBÀ YẸN","Что ты скажешь тому ребёнку?":"Kí lo máa sọ fún ọmọ yẹn?","Представь себя в том возрасте. Сейчас ты взрослый человек и можешь сказать то, чего тогда никто не сказал. Выбери фразы или напиши своё письмо.":"Fojú inú wo ara rẹ ní ọjọ́ orí yẹn. Báyìí o ti dàgbà, o sì lè sọ ohun tí kò sí ẹni tó sọ nígbà yẹn. Yan gbólóhùn tàbí kọ lẹ́tà tìrẹ.","Моё письмо себе в детстве (необязательно)":"Lẹ́tà mi sí ara mi ní ìgbà èwe (kò pọndandan)","Привет. Я — это ты через много лет. Вот что мне хочется тебе сказать…":"Ẹ n lẹ. Èmi ni ìwọ lẹ́yìn ọ̀pọ̀ ọdún. Ohun tí mo fẹ́ sọ fún ọ nìyí…","ТВОИ СЛОВА":"Ọ̀RỌ̀ RẸ","Письмо никуда не отправляется и не сохраняется.":"A kò fi lẹ́tà náà ránṣẹ́ síbìkan, a kò sì fi pamọ́.","07 · ОТПУСТИТЬ":"07 · JẸ́ KÓ LỌ","Как ты хочешь завершить?":"Báwo lo ṣe fẹ́ parí?","Отпустить — не значит забыть. Это значит перестать носить это с собой каждый день. Выбери, что подходит сейчас.":"Jíjẹ́ kó lọ kò túmọ̀ sí gbígbàgbé. Ó túmọ̀ sí dídẹ́kun gbígbé e kiri lójoojúmọ́. Yan ohun tó bá a mu báyìí.","Отпустить с выдохом":"Jẹ́ kó lọ pẹ̀lú mímí síta","Три медленных выдоха. С каждым представь, что тяжесть выходит из тела.":"Mí síta díẹ̀díẹ̀ lẹ́ẹ̀mẹ́ta. Pẹ̀lú ọ̀kọ̀ọ̀kan, fojú inú wo bí ìwúwo ṣe ń jáde kúrò lára rẹ.","Убрать в контейнер":"Fi sínú àpótí","Представь прочную коробку. Положи туда это воспоминание и закрой. Оно будет там, пока ты не решишь вернуться к нему — например, со специалистом.":"Fojú inú wo àpótí tó lágbára. Fi ìrántí yìí sínú rẹ̀ kí o sì tì í. Yóò wà níbẹ̀ títí o fi pinnu láti padà sí i — fún àpẹẹrẹ, pẹ̀lú amọ̀ṣẹ́.","Стереть написанное":"Pa ohun tí mo kọ rẹ́","Если письмо написано — сотри его. Слова уже сказаны, им не нужно оставаться на экране.":"Bí a bá ti kọ lẹ́tà — pa á rẹ́. A ti sọ ọ̀rọ̀ náà, kò nílò láti wà lórí ojú-ìwé.","Коробка закрыта. Только тебе решать, когда её открыть.":"A ti tì àpótí náà. Ìwọ nìkan ló máa pinnu ìgbà tí o máa ṣí i.","Написанное стёрто. То, что важно, осталось с тобой.":"A ti pa ohun tí a kọ rẹ́. Ohun tó ṣe pàtàkì ṣì wà pẹ̀lú rẹ.","Сделай выдох длиннее вдоха. И ещё раз. И ещё.":"Mí síta pẹ́ ju mímí sínú lọ. Lẹ́ẹ̀kan sí i. Àti lẹ́ẹ̀kan sí i.","Насколько неспокойно сейчас?":"Báwo ni ọkàn rẹ ṣe dàrú tó báyìí?","Завершить":"Parí","Полная политика конфиденциальности":"Ìlànà ìpamọ́ kíkún","03 / БЕЗ КАРТЫ":"03 / LÁÌSÍ MÁÀPÙ","Идеи, которые не нужно искать":"Àwọn èrò tí kò nílò ìwákiri","Поиск новых мест сейчас недоступен. Любимые места и идеи без карты остаются здесь. Попробуй позже или укажи другой район.":"Wíwá àwọn ibi tuntun kò ṣeé ṣe báyìí. Àwọn ibi tí o fẹ́ràn àti àwọn èrò láìsí máàpù ṣì wà níbí. Gbìyànjú lẹ́yìn náà tàbí yan agbègbè míì.","Ближайший сквер или двор с деревьями: пятнадцать минут неспешной прогулки.":"Ọgbà kékeré tó sún mọ́ ọ jù tàbí àgbàlá tó ní igi: ìṣẹ́jú mẹ́ẹ̀ẹ́dógún ìrìn pẹ̀lẹ́.","Сад, оранжерея или клумбы у дома: посмотреть на растения вблизи.":"Ọgbà, ilé ewéko tàbí ibùsùn òdòdó nítòsí ilé: wo àwọn ewéko lódodo.","Библиотека или книжный магазин: тихое место, где не нужно ничего покупать.":"Ilé ìkàwé tàbí ilé ìtajà ìwé: ibi ìdákẹ́jẹ́ tí o kò nílò láti ra nǹkan kan.","Кафе с окном: чай и полчаса без телефона.":"Kafé tó ní fèrèsé: tíì àti ìdajì wákàtí láìsí fóònù.","Местный музей или выставка: в будни там обычно тихо.":"Ilé ìṣẹ̀ǹbáyé tàbí àfihàn àdúgbò: ó máa ń dákẹ́ ní ọjọ́ iṣẹ́.","Мост, набережная или высокая точка с видом на город.":"Afárá, etí odò tàbí ibi gíga tí o ti lè rí ìlú.","Небольшое место с домашней едой, куда можно прийти не спеша.":"Ibi kékeré tó ní oúnjẹ ilé tí o lè lọ láìkánjú.","Галерея или выставочный зал: новое для глаз без спешки.":"Ilé àwòrán tàbí gbọ̀ngàn àfihàn: nǹkan tuntun fún ojú, láìkánjú.","Кино на дневной сеанс: в зале меньше людей.":"Sinimá ọ̀sán: ènìyàn díẹ̀ ló wà nínú gbọ̀ngàn.","Афиша ближайшего театра или концерта на неделю.":"Ètò ọ̀sẹ̀ yìí ní ilé ìtàgé tàbí gbọ̀ngàn orin tó sún mọ́ ọ.","Прогулка по незнакомой улице в своём районе.":"Rírìn ní òpópónà tí o kò mọ̀ ní àdúgbò rẹ."},"lex":{"emo":{"fear":["àníyàn","aniyan","ẹ̀rù","eru","ìbẹ̀rù","iberu","mo bẹ̀rù","ìdààmú","idaamu"],"sad":["ìbànújẹ́","ibanuje","inú mi bàjẹ́","inu mi baje","mo ń sunkún","sunkun","ẹkún"],"anger":["ìbínú","ibinu","mo bínú","binu","inú ń bí mi","ìkórìíra"],"tired":["ó rẹ̀ mí","o re mi","àárẹ̀","aare","kò sí agbára","ko si agbara","oorun"],"lonely":["ìdáwà","idawa","mo dá wà","nìkan","kò sí ẹnìkan"],"hurt":["ó dùn mí","o dun mi","ẹ̀gàn","egan","ìtànjẹ","àbùkù"],"shame":["ìtìjú","itiju","ojú tì mí"],"good":["dáadáa","daadaa","ó dára","o dara","inú mi dùn","inu mi dun","àlàáfíà","alaafia"]},"theme":{"work":["iṣẹ́","ise","ọ̀gá","oga","ọ́fíìsì","ẹlẹgbẹ́"],"family":["ẹbí","ebi mi","ìdílé","idile","ìyá","iya","bàbá","baba","ẹ̀gbọ́n","àbúrò","ọmọ"],"love":["olólùfẹ́","ololufe","ọkọ","oko","ìyàwó","iyawo","ìfẹ́","ìbáṣepọ̀"],"friends":["ọ̀rẹ́","ore"],"health":["ìlera","ilera","àìsàn","aisan","ìrora","dókítà","dokita","ilé ìwòsàn"],"money":["owó","owo","gbèsè","gbese","owó oṣù","ìyálé"],"study":["ilé ìwé","ile iwe","ìdánwò","idanwo","ẹ̀kọ́","yunifásítì","olùkọ́"]},"intent":{"bye":["ó dàbọ̀","o dabo","ó dìgbà","o digba","ó dàárọ̀"],"thanks":["ẹ ṣé","e se","o ṣé","o se","ẹ ṣeun","e seun"],"doctor":["ṣé dókítà ni ọ́","dokita ni o","onímọ̀ ọpọlọ"],"who":["ta ni ọ́","ta ni o","ṣé ènìyàn ni ọ́","robot"],"hello":["ẹ n lẹ","e n le","báwo","bawo","ẹ káàárọ̀","kaaro"],"help":["ràn mí lọ́wọ́","ran mi lowo","kí ni kí n ṣe"],"go":["ibo ni kí n lọ","ibo ni ki n lo","jáde","kí ni kí n jẹ"],"nowant":["n kò fẹ́","n ko fe","mi ò fẹ́","fi mí sílẹ̀","dúró"]}},"help":{"lines":["Nàìjíríà: 112"]}};
